use crate::help::wrap_text;

pub struct ParsedScript {
    pub root: Cmd,
    pub functions: Vec<String>,
}

pub struct ParseError {
    pub line_no: usize,
    pub message: String,
}

impl ParseError {
    pub fn syntax(line_no: usize) -> Self {
        ParseError {
            line_no,
            message: format!("syntax error at line {}", line_no),
        }
    }
    pub fn unknown_tag(tag: &str, line_no: usize) -> Self {
        ParseError {
            line_no,
            message: format!("@{}(line {}) is unknown tag", tag, line_no),
        }
    }
    pub fn not_here(tag: &str, line_no: usize) -> Self {
        ParseError {
            line_no,
            message: format!(
                "@{}(line {}) shouldn't be here, @cmd is missing?",
                tag, line_no
            ),
        }
    }
    pub fn missing_fn(name: &str, line_no: usize) -> Self {
        ParseError {
            line_no,
            message: format!("@{}(line {}) missing function?", name, line_no),
        }
    }
    pub fn conflict(name: &str, line_no: usize, prev_line: usize) -> Self {
        ParseError {
            line_no,
            message: format!(
                "{}(line {}) conflicts with cmd or alias at line {}",
                name, line_no, prev_line
            ),
        }
    }
    pub fn exists(tag: &str, line_no: usize, name: &str, prev_line: usize) -> Self {
        ParseError {
            line_no,
            message: format!(
                "@{}(line {}) has '{}' already exists at line {}",
                tag, line_no, name, prev_line
            ),
        }
    }
    pub fn lack_parent(name: &str, line_no: usize) -> Self {
        ParseError {
            line_no,
            message: format!("{}(line {}) lack of parent command", name, line_no),
        }
    }
    pub fn require_fn(line_no: usize, name: &str, kind: &str) -> Self {
        ParseError {
            line_no,
            message: format!("{}: function `{}` is not defined", kind, name),
        }
    }
}

fn is_name_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '.' || c == '-' || c == ':'
}
fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '.' || c == '-' || c == ':'
}
fn is_fn_name_char(c: char) -> bool {
    !matches!(
        c,
        '"' | '$' | '&' | '\'' | ';' | '<' | '>' | '[' | '\\' | ']' | '`' | '{' | '|' | '}'
    ) && !c.is_whitespace()
}

#[derive(Debug)]
struct RawTag {
    line_no: usize,
    tag: String,
    text: String,
    extra: Vec<String>,
}

fn split_tag_content(line: &str) -> Option<(String, String)> {
    // returns (tag, text) if this is a tag line
    if !line.starts_with('#') {
        return None;
    }
    let content = if line.len() == 1 {
        ""
    } else if line.as_bytes()[1] == b' ' {
        &line[2..]
    } else {
        &line[1..]
    };
    if !content.starts_with('@') {
        return None;
    }
    let rest = &content[1..];
    let tag: String = rest.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
    if tag.is_empty() {
        return None;
    }
    let text = rest[tag.len()..].to_string();
    Some((tag, text))
}

pub fn parse_script(content: &str, stem: &str) -> Result<ParsedScript, ParseError> {
    let lines: Vec<&str> = content.split('\n').collect();
    let mut items: Vec<RawTag> = vec();
    let mut functions: Vec<(String, usize)> = vec();

    let mut i = 0usize;
    while i < lines.len() {
        let line = lines[i];
        let line_no = i + 1;
        if let Some((tag, text)) = split_tag_content(line) {
            let mut extra = vec();
            let mut j = i + 1;
            while j < lines.len() {
                let l = lines[j];
                if l.starts_with('#') {
                    if split_tag_content(l).is_some() {
                        break;
                    }
                    let c = if l.len() == 1 {
                        ""
                    } else if l.as_bytes()[1] == b' ' {
                        &l[2..]
                    } else {
                        &l[1..]
                    };
                    extra.push(c.to_string());
                    j += 1;
                } else {
                    break;
                }
            }
            items.push(RawTag {
                line_no,
                tag,
                text,
                extra,
            });
            i = j;
            continue;
        }
        // non-comment line
        if let Some(name) = detect_function(line) {
            functions.push((name, line_no));
        }
        i += 1;
    }

    // build tree
    let mut root = Cmd {
        name: stem.to_string(),
        describe: String::new(),
        version: None,
        aliases: vec(),
        args: vec(),
        positionals: vec(),
        envs: vec(),
        subcommands: vec(),
        command_fn: None,
        meta: Meta::default(),
        is_root: true,
        has_function: false,
    };
    // (parent_path, command) we use a recursive structure with path tracking
    struct Pending {
        line_no: usize,
        cmd_line_no: usize,
        cmd: Cmd,
    }
    let mut cur: Option<Pending> = None;
    let mut done: bool = false; // a function definition has closed the current context

    for it in items {
        let text = it.text.clone();
        let trimmed = text.trim().to_string();
        match it.tag.as_str() {
            "cmd" => {
                if done {
                    // allowed
                }
                if trimmed.is_empty() {
                    // error later if no function
                }
                cur = Some(Pending {
                    line_no: it.line_no,
                    cmd_line_no: it.line_no,
                    cmd: Cmd {
                        name: stem.to_string(),
                        describe: trimmed,
                        version: None,
                        aliases: vec(),
                        args: vec(),
                        positionals: vec(),
                        envs: vec(),
                        subcommands: vec(),
                        command_fn: None,
                        meta: Meta::default(),
                        is_root: false,
                        has_function: false,
                    },
                });
            }
            "alias" => {
                let aliases = match parse_alias_list(&trimmed) {
                    Some(a) => a,
                    None => return Err(ParseError::unknown_tag("alias", it.line_no)),
                };
                match cur.as_mut() {
                    Some(p) => {
                        for a in aliases {
                            if !p.cmd.aliases.contains(&a) {
                                p.cmd.aliases.push(a);
                            }
                        }
                    }
                    None => {
                        // root: silently ignored
                    }
                }
            }
            "describe" => {
                let mut d = trimmed;
                for e in &it.extra {
                    d.push('\n');
                    d.push_str(e);
                }
                match cur.as_mut() {
                    Some(p) => p.cmd.describe = d,
                    None => root.describe = d,
                }
            }
            "meta" => {
                match cur.as_mut() {
                    Some(p) => apply_meta(&mut p.cmd, &trimmed, it.line_no)?,
                    None => apply_meta(&mut root, &trimmed, it.line_no)?,
                }
            }
            "arg" => {
                if cur.is_none() {
                    return Err(ParseError::not_here("arg", it.line_no));
                }
                let p = cur.as_mut().unwrap();
                let (pos, used_lines) = parse_positional(&trimmed, &it.extra, it.line_no)?;
                p.cmd.positionals.push(pos);
                let _ = used_lines;
            }
            "option" => {
                if cur.is_none() {
                    return Err(ParseError::not_here("option", it.line_no));
                }
                let p = cur.as_mut().unwrap();
                let arg = parse_option(&trimmed, &it.extra, it.line_no, false)?;
                p.cmd.args.push(arg);
            }
            "flag" => {
                if cur.is_none() {
                    return Err(ParseError::not_here("flag", it.line_no));
                }
                let p = cur.as_mut().unwrap();
                let arg = parse_option(&trimmed, &it.extra, it.line_no, true)?;
                p.cmd.args.push(arg);
            }
            "env" => {
                if cur.is_none() {
                    return Err(ParseError::not_here("env", it.line_no));
                }
                let p = cur.as_mut().unwrap();
                let env = parse_env(&trimmed, &it.extra, it.line_no)?;
                p.cmd.envs.push(env);
            }
            t => return Err(ParseError::unknown_tag(t, it.line_no)),
        }
    }

    // check for a pending @cmd without a function: report the first one
    if let Some(p) = &cur {
        if p.cmd.command_fn.is_none() {
            return Err(ParseError::missing_fn("cmd", p.cmd_line_no));
        }
    }

    // assign functions to commands
    let fn_names: Vec<String> = functions.iter().map(|(n, _)| n.clone()).collect();
    if fn_names.iter().any(|n| n == "main") {
        root.command_fn = Some("main".to_string());
        root.has_function = true;
    }
    Ok(ParsedScript {
        root,
        functions: fn_names,
    })
}

fn detect_function(line: &str) -> Option<String> {
    // ^(function\s+)?NAME\s*\(\s*\)
    let mut rest = line;
    if let Some(r) = rest.strip_prefix("function") {
        if r.starts_with(char::is_whitespace) {
            let name: String = r.trim_start().chars().take_while(|c| is_fn_name_char(*c)).collect();
            if !name.is_empty() {
                return Some(name);
            }
        }
    }
    // normal form
    let name: String = line.chars().take_while(|c| is_fn_name_char(*c)).collect();
    if name.is_empty() {
        return None;
    }
    let after = &line[name.len()..];
    let after = after.trim_start();
    if after.starts_with('(') {
        let inner = &after[1..];
        let inner = inner.trim_start();
        if let Some(r) = inner.strip_prefix(')') {
            return Some(name);
        }
    }
    None
}
RSEOF
echo ok"}

