fn is_fn_name_char(c: char) -> bool {
    !matches!(c, '"' | '$' | '&' | '\'' | ';' | '<' | '>' | '[' | '\\' | ']' | '`' | '{' | '|' | '}')
        && !c.is_whitespace()
}

fn is_arg_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '.' || c == '-' || c == ':'
}

struct RawTag {
    line_no: usize,
    tag: String,
    text: String,
    extra: Vec<String>,
}

fn content_of_comment(line: &str) -> &str {
    if line.len() == 1 {
        ""
    } else if line.as_bytes()[1] == b' ' {
        &line[2..]
    } else {
        &line[1..]
    }
}

fn split_tag_content(line: &str) -> Option<(String, String)> {
    if !line.starts_with('#') {
        return None;
    }
    let content = content_of_comment(line);
    if !content.starts_with('@') {
        return None;
    }
    let rest = &content[1..];
    let tag: String = rest.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
    if tag.is_empty() {
        return None;
    }
    Some((tag, rest[tag.len()..].to_string()))
}

fn detect_function(line: &str) -> Option<String> {
    if let Some(r) = line.strip_prefix("function") {
        if r.starts_with(char::is_whitespace) {
            let name: String =
                r.trim_start().chars().take_while(|c| is_fn_name_char(*c)).collect();
            if !name.is_empty() {
                return Some(name);
            }
        }
    }
    let name: String = line.chars().take_while(|c| is_fn_name_char(*c)).collect();
    if name.is_empty() {
        return None;
    }
    let after = line[name.len()..].trim_start();
    if let Some(inner) = after.strip_prefix('(') {
        if inner.trim_start().starts_with(')') {
            return Some(name);
        }
    }
    None
}

struct Node {
    parent: usize,
    cmd: Cmd,
    cmd_line: usize,
}

pub fn parse_script(content: &str, stem: &str) -> Result<ParsedScript, ParseError> {
    let lines: Vec<&str> = content.split('\n').collect();
    let mut items: Vec<RawTag> = vec();
    let mut functions: Vec<(String, usize)> = vec();

    let mut i = 0usize;
    while i < lines.len() {
        let line = lines[i];
        let line_no = i + 1;
        if let Some((tag, text)) = split_tag_content(line) {
            let mut extra = vec();
            let mut j = i + 1;
            while j < lines.len() {
                let l = lines[j];
                if l.starts_with('#') {
                    if split_tag_content(l).is_some() {
                        break;
                    }
                    extra.push(content_of_comment(l).to_string());
                    j += 1;
                } else {
                    break;
                }
            }
            items.push(RawTag { line_no, tag, text, extra });
            i = j;
            continue;
        }
        if let Some(name) = detect_function(line) {
            functions.push((name, line_no));
        }
        i += 1;
    }

    let mut nodes: Vec<Node> = vec![Node {
        parent: usize::MAX,
        cmd: Cmd::new(stem.to_string(), true),
        cmd_line: 0,
    }];
    let mut cur: Option<usize> = None;
    let mut cur_alias_line: Vec<(String, usize)> = vec(); // name -> line per parent (root)
    let mut parent_registered: Vec<Vec<(String, usize)>> = vec();

    for it in &items {
        let text = it.text.trim().to_string();
        match it.tag.as_str() {
            "cmd" => {
                let c = Cmd::new(stem.to_string(), false);
                c.describe = text;
                for e in &it.extra {
                    c.describe.push('\n');
                    c.describe.push_str(e);
                }
                let idx = nodes.len();
                nodes.push(Node { parent: 0, cmd: c, cmd_line: it.line_no });
                cur = Some(idx);
                parent_registered.push(vec());
            }
            "alias" => {
                let aliases = match parse_alias_list(&text) {
                    Some(a) => a,
                    None => return Err(ParseError::unknown_tag("alias", it.line_no)),
                };
                match cur {
                    Some(ci) => {
                        let pi = nodes[ci].parent;
                        for a in aliases {
                            let reg = &mut parent_registered[pi];
                            if let Some(prev) = reg.iter().find(|(n, _)| *n == a) {
                                return Err(ParseError::conflict(
                                    &a,
                                    it.line_no,
                                    prev.1,
                                ));
                            }
                            reg.push((a.clone(), it.line_no));
                            nodes[ci].cmd.aliases.push(a);
                        }
                    }
                    None => {}
                }
            }
            "describe" => {
                let mut d = text;
                for e in &it.extra {
                    d.push('\n');
                    d.push_str(e);
                }
                match cur {
                    Some(ci) => nodes[ci].cmd.describe = d,
                    None => nodes[0].cmd.describe = d,
                }
            }
            "meta" => {
                let ci = cur.unwrap_or(0);
                apply_meta(&mut nodes[ci].cmd, &text, it.line_no)?;
            }
            "arg" | "option" | "flag" | "env" => {
                let ci = match cur {
                    Some(c) => c,
                    None => return Err(ParseError::not_here(&it.tag, it.line_no)),
                };
                match it.tag.as_str() {
                    "arg" => {
                        let p = parse_positional(&text, &it.extra, it.line_no)?;
                        if nodes[ci].cmd.positionals.iter().any(|x| x.id == p.id) {
                            let prev = nodes[ci]
                                .cmd
                                .pos_line
                                .iter()
                                .find(|(n, _)| n == &p.id)
                                .map(|(_, l)| *l)
                                .unwrap_or(0);
                            return Err(ParseError::exists("arg", it.line_no, &p.id, prev));
                        }
                        nodes[ci].cmd.pos_line.push((p.id.clone(), it.line_no));
                        nodes[ci].cmd.positionals.push(p);
                    }
                    "option" | "flag" => {
                        let a = parse_option(&text, &it.extra, it.line_no, it.tag == "flag")?;
                        if let Some(prev) = nodes[ci]
                            .cmd
                            .arg_line
                            .iter()
                            .find(|(n, _)| *n == &a.id)
                            .map(|(_, l)| *l)
                        {
                            return Err(ParseError::exists(&it.tag, it.line_no, &a.id, prev));
                        }
                        nodes[ci].cmd.arg_line.push((a.id.clone(), it.line_no));
                        nodes[ci].cmd.args.push(a);
                    }
                    _ => {
                        let e = parse_env(&text, &it.extra, it.line_no)?;
                        if let Some(prev) = nodes[ci]
                            .cmd
                            .env_line
                            .iter()
                            .find(|(n, _)| *n == &e.id)
                            .map(|(_, l)| *l)
                        {
                            return Err(ParseError::exists("env", it.line_no, &e.id, prev));
                        }
                        nodes[ci].cmd.env_line.push((e.id.clone(), it.line_no));
                        nodes[ci].cmd.envs.push(e);
                    }
                }
            }
            t => return Err(ParseError::unknown_tag(t, it.line_no)),
        }
    }

    // resolve functions
    for (fname, fline) in &functions {
        if let Some(ci) = cur {
            let parts: Vec<&str> = fname.split("::").collect();
            let mut pi = 0usize;
            for p in &parts[..parts.len() - 1] {
                let found = nodes[pi].cmd.subcommands.iter().position(|s| s.name == *p);
                match found {
                    Some(k) => {
                        pi = nodes[pi].cmd.subcommands[k].idx;
                        nodes[pi].cmd.command_fn = None;
                    }
                    None => return Err(ParseError::lack_parent(fname, *fline)),
                }
            }
            let last = parts[parts.len() - 1];
            let node = &mut nodes[ci];
            let pnode = &nodes[node.parent];
            // conflict check
            if pnode.cmd.subcommands.iter().any(|s| s.name == last)
                || pnode.cmd.subcommands.iter().any(|s| s.aliases.iter().any(|a| a == last))
            {
                let prev = pnode.cmd.sub_line.iter().find(|(n, _)| n == last).map(|(_, l)| *l).unwrap_or(0);
                return Err(ParseError::conflict(last, *fline, prev));
            }
            node.cmd.name = last.to_string();
            node.cmd.command_fn = Some(fname.clone());
            node.cmd.has_function = true;
            nodes[node.parent].cmd.subcommands.push(node.cmd.clone());
            nodes[node.parent].cmd.sub_line.push((last.to_string(), *fline));
            cur = None;
        }
    }

    if let Some(ci) = cur {
        if nodes[ci].cmd.command_fn.is_none() {
            return Err(ParseError::missing_fn(nodes[ci].cmd_line));
        }
    }

    if functions.iter().any(|(n, _)| n == "main") {
        nodes[0].cmd.command_fn = Some("main".to_string());
        nodes[0].cmd.has_function = true;
    }

    let _ = cur_alias_line;
    Ok(ParsedScript { root: nodes[0].cmd.clone(), functions: functions.iter().map(|(n, _)| n.clone()).collect() })
}
RSEOF
echo ok"}

