}

pub fn parse_script(content: &str, stem: &str) -> Result<ParsedScript, ParseError> {
    let lines: Vec<&str> = content.split('\n').collect();
    let mut items: Vec<RawTag> = vec();
    let mut functions: Vec<(String, usize)> = vec();

    let mut i = 0usize;
    while i < lines.len() {
        let line = lines[i];
        let line_no = i + 1;
        if let Some((tag, text)) = split_tag_content(line) {
            let mut extra = vec();
            let mut j = i + 1;
            while j < lines.len() {
                let l = lines[j];
                if l.starts_with('#') {
                    if split_tag_content(l).is_some() {
                        break;
                    }
                    extra.push(content_of_comment(l).to_string());
                    j += 1;
                } else {
                    break;
                }
            }
            items.push(RawTag { line_no, tag, text, extra });
            i = j;
            continue;
        }
        if let Some(name) = detect_function(line) {
            functions.push((name, line_no));
        }
        i += 1;
    }

    let mut nodes: Vec<Node> = vec![Node {
        parent: usize::MAX,
        cmd: Cmd::new(stem.to_string(), true),
        cmd_line: 0,
    }];
    let mut cur: Option<usize> = None;
    let mut cur_alias_line: Vec<(String, usize)> = vec(); // name -> line per parent (root)
    let mut parent_registered: Vec<Vec<(String, usize)>> = vec();

