        let text = it.text.trim().to_string();
        match it.tag.as_str() {
            "cmd" => {
                let c = Cmd::new(stem.to_string(), false);
                c.describe = text;
                for e in &it.extra {
                    c.describe.push('\n');
                    c.describe.push_str(e);
                }
                let idx = nodes.len();
                nodes.push(Node { parent: 0, cmd: c, cmd_line: it.line_no });
                cur = Some(idx);
                parent_registered.push(vec());
            }
            "alias" => {
                let aliases = match parse_alias_list(&text) {
                    Some(a) => a,
                    None => return Err(ParseError::unknown_tag("alias", it.line_no)),
                };
                match cur {
                    Some(ci) => {
                        let pi = nodes[ci].parent;
                        for a in aliases {
                            let reg = &mut parent_registered[pi];
                            if let Some(prev) = reg.iter().find(|(n, _)| *n == a) {
                                return Err(ParseError::conflict(
                                    &a,
                                    it.line_no,
                                    prev.1,
                                ));
                            }
                            reg.push((a.clone(), it.line_no));
                            nodes[ci].cmd.aliases.push(a);
                        }
                    }
                    None => {}
                }
            }
            "describe" => {
                let mut d = text;
                for e in &it.extra {
                    d.push('\n');
                    d.push_str(e);
                }
                match cur {
                    Some(ci) => nodes[ci].cmd.describe = d,
                    None => nodes[0].cmd.describe = d,
                }
            }
            "meta" => {
                let ci = cur.unwrap_or(0);
                apply_meta(&mut nodes[ci].cmd, &text, it.line_no)?;
            }
            "arg" | "option" | "flag" | "env" => {
                let ci = match cur {
                    Some(c) => c,
                    None => return Err(ParseError::not_here(&it.tag, it.line_no)),
                };
                match it.tag.as_str() {
                    "arg" => {
                        let p = parse_positional(&text, &it.extra, it.line_no)?;
                        if nodes[ci].cmd.positionals.iter().any(|x| x.id == p.id) {
                            let prev = nodes[ci]
                                .cmd
                                .pos_line
                                .iter()
                                .find(|(n, _)| n == &p.id)
                                .map(|(_, l)| *l)
                                .unwrap_or(0);
                            return Err(ParseError::exists("arg", it.line_no, &p.id, prev));
                        }
                        nodes[ci].cmd.pos_line.push((p.id.clone(), it.line_no));
                        nodes[ci].cmd.positionals.push(p);
                    }
                    "option" | "flag" => {
                        let a = parse_option(&text, &it.extra, it.line_no, it.tag == "flag")?;
                        if let Some(prev) = nodes[ci]
                            .cmd
                            .arg_line
                            .iter()
                            .find(|(n, _)| *n == &a.id)
                            .map(|(_, l)| *l)
                        {
                            return Err(ParseError::exists(&it.tag, it.line_no, &a.id, prev));
                        }
                        nodes[ci].cmd.arg_line.push((a.id.clone(), it.line_no));
                        nodes[ci].cmd.args.push(a);
                    }
                    _ => {
                        let e = parse_env(&text, &it.extra, it.line_no)?;
                        if let Some(prev) = nodes[ci]
                            .cmd
                            .env_line
                            .iter()
                            .find(|(n, _)| *n == &e.id)
                            .map(|(_, l)| *l)
                        {
                            return Err(ParseError::exists("env", it.line_no, &e.id, prev));
                        }
                        nodes[ci].cmd.env_line.push((e.id.clone(), it.line_no));
                        nodes[ci].cmd.envs.push(e);
                    }
                }
            }
            t => return Err(ParseError::unknown_tag(t, it.line_no)),
        }
    }

    // resolve functions
    for (fname, fline) in &functions {
        if let Some(ci) = cur {
            let parts: Vec<&str> = fname.split("::").collect();
            let mut pi = 0usize;
            for p in &parts[..parts.len() - 1] {
                let found = nodes[pi].cmd.subcommands.iter().position(|s| s.name == *p);
                match found {
                    Some(k) => {
                        pi = nodes[pi].cmd.subcommands[k].idx;
                        nodes[pi].cmd.command_fn = None;
                    }
                    None => return Err(ParseError::lack_parent(fname, *fline)),
                }
            }
            let last = parts[parts.len() - 1];
            let node = &mut nodes[ci];
            let pnode = &nodes[node.parent];
            // conflict check
            if pnode.cmd.subcommands.iter().any(|s| s.name == last)
                || pnode.cmd.subcommands.iter().any(|s| s.aliases.iter().any(|a| a == last))
            {
                let prev = pnode.cmd.sub_line.iter().find(|(n, _)| n == last).map(|(_, l)| *l).unwrap_or(0);
                return Err(ParseError::conflict(last, *fline, prev));
            }
            node.cmd.name = last.to_string();
            node.cmd.command_fn = Some(fname.clone());
            node.cmd.has_function = true;
            nodes[node.parent].cmd.subcommands.push(node.cmd.clone());
            nodes[node.parent].cmd.sub_line.push((last.to_string(), *fline));
            cur = None;
        }
    }

    if let Some(ci) = cur {
        if nodes[ci].cmd.command_fn.is_none() {
            return Err(ParseError::missing_fn(nodes[ci].cmd_line));
        }
    }

    if functions.iter().any(|(n, _)| n == "main") {
        nodes[0].cmd.command_fn = Some("main".to_string());
        nodes[0].cmd.has_function = true;
    }

    let _ = cur_alias_line;
    Ok(ParsedScript { root: nodes[0].cmd.clone(), functions: functions.iter().map(|(n, _)| n.clone()).collect() })
}
