    ) && !c.is_whitespace()
}

fn is_arg_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '.' || c == '-' || c == ':'
}

fn content_of_comment(line: &str) -> &str {
    if line.len() == 1 {
        ""
    } else if line.as_bytes()[1] == b' ' {
        &line[2..]
    } else {
        &line[1..]
    }
}

fn split_tag_content(line: &str) -> Option<(String, String)> {
    if !line.starts_with('#') {
        return None;
    }
    let content = content_of_comment(line);
    if !content.starts_with('@') {
        return None;
    }
    let rest = &content[1..];
    let tag: String = rest.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
    if tag.is_empty() {
        return None;
    }
    Some((tag, rest[tag.len()..].to_string()))
}

