    if let Some(r) = line.strip_prefix("function") {
        if r.starts_with(char::is_whitespace) {
            let name: String = r.trim_start().chars().take_while(|c| is_fn_name_char(*c)).collect();
            if !name.is_empty() {
                return Some(name);
            }
        }
    }
    let name: String = line.chars().take_while(|c| is_fn_name_char(*c)).collect();
    if name.is_empty() {
        return None;
    }
    let after = line[name.len()..].trim_start();
    if let Some(inner) = after.strip_prefix('(') {
