    describe: String,
    aliases: Vec<(String, usize)>,
    args: Vec<(Arg, usize)>,
    positionals: Vec<(Positional, usize)>,
    envs: Vec<(Env, usize)>,
    metas: Vec<Meta>,
    fn_name: Option<String>,
