    Tag { line_no: usize, tag: String, text: String, extra: Vec<String> },
    Fn { line_no: usize, name: String },
}

pub fn parse_alias_list(text: &str) -> Option<Vec<String>> {
    let mut out = vec![];
    let mut rest = text.trim_start();
    if rest.is_empty() {
        return None;
    }
    loop {
        let word: String = rest
            .chars()
            .take_while(|c| is_arg_word_char(*c))
            .collect();
        if word.is_empty() {
            break;
        }
        out.push(word.clone());
        rest = rest[word.len()..].trim_start();
        match rest.chars().next() {
            Some(',') => {
                rest = rest[1..].trim_start();
            }
            _ => break,
        }
    }
    Some(out)
}

fn tokenize_with_pos(s: &str) -> Vec<(usize, usize)> {
    // returns (start, end) of whitespace separated tokens
    let b = s.as_bytes();
    let mut out = vec![];
    let mut i = 0;
    while i < b.len() {
        if b[i].is_ascii_whitespace() {
            i += 1;
            continue;
        }
        let start = i;
        while i < b.len() && !b[i].is_ascii_whitespace() {
            i += 1;
        }
        out.push((start, i));
    }
    out
}

pub fn parse_script(content: &str, stem: &str) -> Result<ParsedScript, ParseError> {
    let lines: Vec<&str> = content.split('\n').collect();
    let mut events: Vec<Event> = vec();
    let mut i = 0usize;
    while i < lines.len() {
        let line = lines[i];
        let line_no = i + 1;
        if let Some((tag, text)) = split_tag_content(line) {
            let mut extra = vec();
            let mut j = i + 1;
            while j < lines.len() {
                let l = lines[j];
                if l.starts_with('#') {
                    if split_tag_content(l).is_some() {
                        break;
                    }
                    extra.push(content_of_comment(l).to_string());
                    j += 1;
                } else {
                    break;
                }
            }
            events.push(Event::Tag { line_no, tag, text, extra });
            i = j;
            continue;
        }
        if let Some(name) = detect_function(line) {
            events.push(Event::Fn { line_no, name });
        }
        i += 1;
    }

    let mut root = Group { cmd_line: 0, ..Default::default() };
    let mut root_metas: Vec<Meta> = vec();
    let mut groups: Vec<Group> = vec();
    let mut cur: Option<usize> = None;

    for ev in &events {
        match ev {
            Event::Fn { line_no, name } => {
                if let Some(gi) = cur {
                    groups[gi].fn_name = Some(name.clone());
                    groups[gi].fn_line = *line_no;
                    cur = None;
                }
            }
            Event::Tag { line_no, tag, text, extra } => {
                let t = text.trim().to_string();
                match tag.as_str() {
                    "cmd" => {
                        let mut g = Group { cmd_line: *line_no, ..Default::default() };
                        g.describe = t.clone();
                        for e in extra {
                            g.describe.push('\n');
                            g.describe.push_str(e);
                        }
                        groups.push(g);
                        cur = Some(groups.len() - 1);
                    }
                    "alias" => {
                        let aliases = match parse_alias_list(&t) {
                            Some(a) => a,
                            None => return Err(ParseError::unknown_tag("alias", *line_no)),
                        };
                        if let Some(gi) = cur {
                            for a in aliases {
                                if let Some(prev) =
                                    groups[gi].aliases.iter().find(|(n, _)| *n == a)
                                {
                                    let l = prev.1;
                                    return Err(ParseError::conflict(&a, *line_no, l));
                                }
                                groups[gi].aliases.push((a, *line_no));
                            }
                        }
                    }
                    "describe" => {
                        let mut d = t;
                        for e in extra {
                            d.push('\n');
                            d.push_str(e);
                        }
                        match cur {
                            Some(gi) => groups[gi].describe = d,
                            None => root.describe = d,
                        }
                    }
                    "meta" => {
                        let m = apply_meta(&t, *line_no)?;
                        match cur {
                            Some(gi) => groups[gi].metas.push(m),
                            None => root_metas.push(m),
                        }
                    }
                    "arg" | "option" | "flag" | "env" => {
                        let gi = match cur {
                            Some(c) => c,
                            None => return Err(ParseError::not_here(tag, *line_no)),
                        };
                        match tag.as_str() {
                            "arg" => {
                                let p = parse_positional(&t, extra, *line_no)?;
                                if let Some(prev) = groups[gi]
                                    .positionals
                                    .iter()
                                    .find(|(x, _)| x.id == p.id)
                                {
                                    let l = prev.1;
                                    return Err(ParseError::exists("arg", *line_no, &p.id, l));
                                }
                                groups[gi].positionals.push((p, *line_no));
                            }
                            "option" | "flag" => {
                                let a =
                                    parse_option(&t, extra, *line_no, tag == "flag")?;
                                if let Some(prev) =
                                    groups[gi].args.iter().find(|(x, _)| x.id == a.id)
                                {
                                    let l = prev.1;
                                    return Err(ParseError::exists(tag, *line_no, &a.id, l));
                                }
                                groups[gi].args.push((a, *line_no));
                            }
                            _ => {
                                let e = parse_env(&t, extra, *line_no)?;
                                if let Some(prev) =
                                    groups[gi].envs.iter().find(|(x, _)| x.id == e.id)
                                {
                                    let l = prev.1;
                                    return Err(ParseError::exists("env", *line_no, &e.id, l));
                                }
                                groups[gi].envs.push((e, *line_no));
                            }
                        }
                    }
                    other => return Err(ParseError::unknown_tag(other, *line_no)),
                }
            }
        }
    }

    // check pending groups without functions
    for g in &groups {
        if g.fn_name.is_none() {
            return Err(ParseError::missing_fn(g.cmd_line));
        }
    }

    // build tree
    let mut nodes: Vec<(usize, Cmd)> = vec![(usize::MAX, Cmd::new(stem.to_string(), true))];
    for g in &groups {
        let fname = g.fn_name.clone().unwrap();
        let parts: Vec<&str> = fname.split("::").collect();
        let mut pi = 0usize;
        if parts.len() > 1 {
            for p in &parts[..parts.len() - 1] {
                let found = nodes
                    .iter()
                    .position(|(pp, c)| *pp == pi && c.name == *p);
                match found {
                    Some(k) => {
                        pi = k;
                        nodes[pi].1.command_fn = None;
                    }
                    None => return Err(ParseError::lack_parent(&fname, g.fn_line)),
                }
            }
        }
        let last = parts[parts.len() - 1].to_string();
        // conflict check
        let conflict = nodes
            .iter()
            .any(|(pp, c)| *pp == pi && (c.name == last || c.aliases.iter().any(|a| a == &last)));
        if conflict {
            let prev = nodes
                .iter()
                .filter(|(pp, c)| *pp == pi)
                .find(|(_, c)| c.name == last)
                .map(|(_, c)| c)
                .and_then(|_| None);
            let _ = prev;
            let pline = groups
                .iter()
                .find(|gg| gg.fn_name.as_deref() == Some(last.as_str()))
                .map(|gg| gg.fn_line)
                .unwrap_or(0);
            return Err(ParseError::conflict(&last, g.fn_line, pline));
        }
        let mut cmd = Cmd::new(last.clone(), false);
        cmd.describe = g.describe.clone();
        cmd.aliases = g.aliases.iter().map(|(a, _)| a.clone()).collect();
        cmd.args = g.args.iter().map(|(a, _)| a.clone()).collect();
        cmd.positionals = g.positionals.iter().map(|(p, _)| p.clone()).collect();
        cmd.envs = g.envs.iter().map(|(e, _)| e.clone()).collect();
        cmd.command_fn = Some(fname.clone());
        cmd.has_function = true;
        for m in &g.metas {
            merge_meta(&mut cmd.meta, m);
        }
        let idx = nodes.len();
        nodes.push((pi, cmd));
        let _ = idx;
    }

    let mut rc = Cmd::new(stem.to_string(), true);
    rc.describe = root.describe.clone();
    rc.args = root.args.iter().map(|(a, _)| a.clone()).collect();
    rc.positionals = root.positionals.iter().map(|(p, _)| p.clone()).collect();
    rc.envs = root.envs.iter().map(|(e, _)| e.clone()).collect();
    for m in root_metas.iter().chain(root.metas.iter()) {
        merge_meta(&mut rc.meta, m);
    }
    rc.subcommands = nodes
        .iter()
        .filter(|(p, _)| *p == 0 && nodes.iter().any(|_| true))
        .map(|(_, c)| c.clone())
        .collect();
    // fix: subcommands of the root must be direct children in document order
    let mut root_subs: Vec<Cmd> = vec();
    let mut used = vec![];
    for (idx, (p, c)) in nodes.iter().enumerate() {
        if idx == 0 {
            continue;
        }
        if *p == 0 && !used.contains(&idx) {
            root_subs.push(c.clone());
        }
    }
    rc.subcommands = root_subs;

    // resolve subcommand lists recursively
    fn attach(nodes: &[(usize, Cmd)], pi: usize) -> Vec<Cmd> {
        let mut out = vec![];
        for (idx, (p, c)) in nodes.iter().enumerate() {
            if idx == 0 {
                continue;
            }
            if *p == pi {
                let mut c = c.clone();
                c.subcommands = attach(nodes, idx);
                out.push(c);
            }
        }
        out
    }
    rc.subcommands = attach(&nodes, 0);

    // inherit flag options
    if rc.meta.inherit_flag_options {
        let inherited: Vec<Arg> = rc
            .args
            .iter()
            .filter(|a| a.id != "help" && a.id != "version")
            .map(|a| {
                let mut a = a.clone();
                a.inherited = true;
                a
            })
            .collect();
        fn apply_inherit(c: &mut Cmd, inh: &[Arg], depth: usize) {
            for s in c.subcommands.iter_mut() {
                for a in inh.iter().rev() {
                    let mut a2 = a.clone();
                    a2.inherited = true;
                    s.args.insert(0, a2);
                }
                if depth < 8 {
                    apply_inherit(s, inh, depth + 1);
                }
            }
        }
        apply_inherit(&mut rc, &inherited, 0);
    }

    if let Some(m) = rc.metas.iter().find(|m| m.default_subcommand.is_some()) {
        rc.meta.default_subcommand = m.default_subcommand.clone();
    }

    if functions.iter().any(|(n, _)| n == "main") {
        rc.command_fn = Some("main".to_string());
        rc.has_function = true;
    }

    Ok(ParsedScript {
        root: rc,
        functions: functions.iter().map(|(n, _)| n.clone()).collect(),
    })
}
