pub struct ParseError {
    pub line_no: usize,
    pub message: String,
}

impl ParseError {
    pub fn syntax(line_no: usize) -> Self {
        ParseError { line_no, message: format!("syntax error at line {}", line_no) }
    }
    pub fn unknown_tag(tag: &str, line_no: usize) -> Self {
        ParseError { line_no, message: format!("@{}(line {}) is unknown tag", tag, line_no) }
    }
    pub fn not_here(tag: &str, line_no: usize) -> Self {
        ParseError {
            line_no,
            message: format!("@{}(line {}) shouldn't be here, @cmd is missing?", tag, line_no),
        }
    }
    pub fn missing_fn(line_no: usize) -> Self {
        ParseError { line_no, message: format!("@cmd(line {}) missing function?", line_no) }
    }
    pub fn conflict(name: &str, line_no: usize, prev_line: usize) -> Self {
        ParseError {
            line_no,
            message: format!(
                "{}(line {}) conflicts with cmd or alias at line {}",
                name, line_no, prev_line
            ),
        }
    }
    pub fn exists(tag: &str, line_no: usize, name: &str, prev_line: usize) -> Self {
        ParseError {
            line_no,
            message: format!(
                "@{}(line {}) has '{}' already exists at line {}",
                tag, line_no, name, prev_line
            ),
        }
    }
    pub fn lack_parent(name: &str, line_no: usize) -> Self {
        ParseError { line_no, message: format!("{}(line {}) lack of parent command", name, line_no) }
    }
}

fn is_fn_name_char(c: char) -> bool {
    !matches!(
        c,
        '"' | '$' | '&' | '\'' | ';' | '<' | '>' | '[' | '\\' | ']' | '`' | '{' | '|' | '}'
    ) && !c.is_whitespace()
}

fn is_arg_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '.' || c == '-' || c == ':'
}

fn content_of_comment(line: &str) -> &str {
    if line.len() == 1 {
        ""
    } else if line.as_bytes()[1] == b' ' {
        &line[2..]
    } else {
        &line[1..]
    }
}

fn split_tag_content(line: &str) -> Option<(String, String)> {
    if !line.starts_with('#') {
        return None;
    }
    let content = content_of_comment(line);
    if !content.starts_with('@') {
        return None;
    }
    let rest = &content[1..];
    let tag: String = rest.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
    if tag.is_empty() {
        return None;
    }
    Some((tag, rest[tag.len()..].to_string()))
}

fn detect_function(line: &str) -> Option<String> {
    if let Some(r) = line.strip_prefix("function") {
        if r.starts_with(char::is_whitespace) {
            let name: String = r.trim_start().chars().take_while(|c| is_fn_name_char(*c)).collect();
            if !name.is_empty() {
                return Some(name);
            }
        }
    }
    let name: String = line.chars().take_while(|c| is_fn_name_char(*c)).collect();
    if name.is_empty() {
        return None;
    }
    let after = line[name.len()..].trim_start();
    if let Some(inner) = after.strip_prefix('(') {
        if inner.trim_start().starts_with(')') {
            return Some(name);
        }
    }
    None
}

