        .map(|(_, c)| c.clone())
        .collect();
    // fix: subcommands of the root must be direct children in document order
    let mut root_subs: Vec<Cmd> = vec();
    let mut used = vec![];
    for (idx, (p, c)) in nodes.iter().enumerate() {
        if idx == 0 {
            continue;
        }
        if *p == 0 && !used.contains(&idx) {
            root_subs.push(c.clone());
        }
    }
    rc.subcommands = root_subs;

    // resolve subcommand lists recursively
    fn attach(nodes: &[(usize, Cmd)], pi: usize) -> Vec<Cmd> {
        let mut out = vec![];
        for (idx, (p, c)) in nodes.iter().enumerate() {
            if idx == 0 {
                continue;
            }
            if *p == pi {
                let mut c = c.clone();
                c.subcommands = attach(nodes, idx);
                out.push(c);
            }
        }
        out
    }
    rc.subcommands = attach(&nodes, 0);

    // inherit flag options
    if rc.meta.inherit_flag_options {
        let inherited: Vec<Arg> = rc
            .args
            .iter()
            .filter(|a| a.id != "help" && a.id != "version")
            .map(|a| {
                let mut a = a.clone();
                a.inherited = true;
                a
            })
            .collect();
        fn apply_inherit(c: &mut Cmd, inh: &[Arg], depth: usize) {
            for s in c.subcommands.iter_mut() {
                for a in inh.iter().rev() {
                    let mut a2 = a.clone();
                    a2.inherited = true;
                    s.args.insert(0, a2);
                }
                if depth < 8 {
                    apply_inherit(s, inh, depth + 1);
                }
            }
        }
        apply_inherit(&mut rc, &inherited, 0);
    }

    if let Some(m) = rc.metas.iter().find(|m| m.default_subcommand.is_some()) {
        rc.meta.default_subcommand = m.default_subcommand.clone();
    }

    if functions.iter().any(|(n, _)| n == "main") {
        rc.command_fn = Some("main".to_string());
        rc.has_function = true;
    }

    Ok(ParsedScript {
        root: rc,
        functions: functions.iter().map(|(n, _)| n.clone()).collect(),
    })
}
