pub struct Modifiers {
    pub required: bool,
    pub multiple_occurs: bool,
    pub terminated: bool,
    pub delimiter: Option<char>,
    pub prefixed: bool,
    pub assigned: bool,
    pub default: Option<DefaultVal>,
    pub choice: Option<Choice>,
}

pub fn parse_modifiers(rest: &str, defined_fns: &Vec<String>) -> Result<Modifiers, ()> {
    let mut m = Modifiers::default();
    let mut s = rest;
    // prefix / assigned markers
    loop {
        if let Some(r) = s.strip_prefix('-') {
            m.prefixed = true;
            s = r;
            continue;
        }
        if let Some(r) = s.strip_prefix(':') {
            m.assigned = true;
            s = r;
            continue;
        }
        break;
    }
    // occurrence flags
    let mut occurred = false;
    loop {
        if let Some(r) = s.strip_prefix('!') {
            if occurred {
                return Err(());
            }
            m.required = true;
            occurred = true;
            s = r;
            continue;
        }
        if let Some(r) = s.strip_prefix('*') {
            if occurred {
                return Err(());
            }
            m.multiple_occurs = true;
            occurred = true;
            s = r;
            continue;
        }
        if let Some(r) = s.strip_prefix('+') {
            if occurred {
                return Err(());
            }
            m.required = true;
            m.multiple_occurs = true;
            occurred = true;
            s = r;
            continue;
        }
        if let Some(r) = s.strip_prefix('~') {
            if occurred {
                return Err(());
            }
            m.terminated = true;
            occurred = true;
            s = r;
            continue;
