pub fn parse_choices(inner: &str, defined_fns: &Vec<String>) -> Result<(Choice, Option<DefaultVal>), ()> {
    if let Some(v) = inner.strip_prefix('?') {
        let v = match v.strip_prefix('`') {
            Some(x) => x,
            None => return Err(()),
        };
        let name = match v.strip_suffix('`') {
            Some(n) => n,
            None => return Err(()),
        };
        if !defined_fns.iter().any(|f| f == name) {
            return Err(());
        }
        return Ok((Choice::Fn(name.to_string(), false), None));
    }
    if let Some(v) = inner.strip_prefix('`') {
        let name = match v.strip_suffix('`') {
            Some(n) => n,
            None => return Err(()),
        };
        if !defined_fns.iter().any(|f| f == name) {
            return Err(());
        }
        return Ok((Choice::Fn(name.to_string(), true), None));
    }
    // [=]values separated by |
    let mut def: Option<DefaultVal> = None;
    let body = if let Some(v) = inner.strip_prefix('=') {
        // first value is the default
        let vals: Vec<&str> = v.split('|').collect();
        if vals.is_empty() {
            return Err(());
        }
        def = Some(DefaultVal::Value(vals[0].to_string()));
        vals.to_vec()
    } else {
        inner.split('|').collect()
    };
    let vals: Vec<String> = body.iter().map(|s| s.to_string()).collect();
    if vals.is_empty() {
        return Err(());
    }
    Ok((Choice::Values(vals), def))
}

pub fn parse_env_modifiers(rest: &str, defined_fns: &Vec<String>) -> Result<(bool, Option<DefaultVal>, Option<Choice>), ()> {
    let mut required = false;
    let mut s = rest;
    if let Some(r) = s.strip_prefix('!') {
        required = true;
        s = r;
    }
    if s.is_empty() {
        return Ok((required, None, None));
    }
    if let Some(v) = s.strip_prefix('=') {
        return Ok((required, Some(DefaultVal::Value(v.to_string())), None));
    }
    if let Some(v) = s.strip_prefix('`') {
        let name = match v.strip_suffix('`') {
            Some(n) => n.to_string(),
            None => return Err(()),
        };
        if !defined_fns.iter().any(|f| f == &name) {
            return Err(());
        }
        return Ok((required, Some(DefaultVal::Fn(name)), None));
    }
    if let Some(v) = s.strip_prefix('[') {
        let inner = match v.strip_suffix(']') {
            Some(i) => i.to_string(),
            None => return Err(()),
        };
        let (choice, def) = parse_choices(&inner, defined_fns)?;
        return Ok((required, def, Some(choice)));
    }
    Err(())
}
RSEOF
echo done"}

