use crate::model::*;
use crate::parser::ParseError;

fn is_arg_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '.' || c == '-' || c == ':'
}

pub fn derive_notation(name: &str) -> String {
    let mut s: String = name
        .chars()
        .map(|c| if c == '_' { '-' } else { c.to_ascii_uppercase() })
        .collect();
    if s.is_empty() {
        s = "VALUE".to_string();
    }
    s
}

fn tok_at(s: &str, t: (usize, usize)) -> &str {
    &s[t.0..t.1]
}

pub fn tokenize_with_pos(s: &str) -> Vec<(usize, usize)> {
    let b = s.as_bytes();
    let mut out = vec![];
    let mut i = 0;
    while i < b.len() {
        if b[i].is_ascii_whitespace() {
            i += 1;
            continue;
        }
        let start = i;
        while i < b.len() && !b[i].is_ascii_whitespace() {
            i += 1;
        }
        out.push((start, i));
    }
    out
}

pub struct NotationSpec {
    pub text: String,
    pub min: u32,
    pub max: u32,
    pub multiple: bool,
    pub terminated: bool,
}

pub fn parse_notation(inner: &str) -> NotationSpec {
    let (mut text, mut min, mut max) = (inner.to_string(), 1u32, 1u32);
    let mut multiple = false;
    let mut terminated = false;
    if let Some(t) = inner.strip_suffix('*') {
        text = t.to_string();
        min = 0;
        max = 32767;
        multiple = true;
    } else if let Some(t) = inner.strip_suffix('+') {
        text = t.to_string();
        min = 1;
        max = 32767;
        multiple = true;
    } else if let Some(t) = inner.strip_suffix('?') {
        text = t.to_string();
        min = 0;
        max = 1;
    } else if let Some(t) = inner.strip_suffix('~') {
        text = t.to_string();
        min = 1;
        max = 32767;
        multiple = true;
        terminated = true;
    }
    NotationSpec { text, min, max, multiple, terminated }
}

#[derive(Debug, Default)]
pub struct Modifiers {
    pub required: bool,
    pub multiple_occurs: bool,
    pub terminated: bool,
    pub delimiter: Option<char>,
    pub prefixed: bool,
    pub assigned: bool,
    pub default: Option<DefaultVal>,
    pub choice: Option<Choice>,
}

pub fn parse_modifiers(rest: &str, defined_fns: &Vec<String>) -> Result<Modifiers, ()> {
    let mut m = Modifiers::default();
    let mut s = rest;
    loop {
        if let Some(r) = s.strip_prefix('-') {
            m.prefixed = true;
            s = r;
            continue;
        }
        if let Some(r) = s.strip_prefix(':') {
            m.assigned = true;
            s = r;
            continue;
        }
        break;
    }
    let mut occurred = false;
    loop {
        if let Some(r) = s.strip_prefix('!') {
            if occurred {
                return Err(());
            }
            m.required = true;
            occurred = true;
            s = r;
            continue;
        }
        if let Some(r) = s.strip_prefix('*') {
            if occurred {
                return Err(());
            }
            m.multiple_occurs = true;
            occurred = true;
            s = r;
            continue;
        }
        if let Some(r) = s.strip_prefix('+') {
            if occurred {
                return Err(());
            }
            m.required = true;
            m.multiple_occurs = true;
            occurred = true;
            s = r;
            continue;
        }
        if let Some(r) = s.strip_prefix('~') {
            if occurred {
                return Err(());
            }
            m.terminated = true;
            occurred = true;
            s = r;
            continue;
        }
        if let Some(r) = s.strip_prefix(',') {
            if !m.multiple_occurs {
                return Err(());
            }
            m.delimiter = Some(',');
            s = r;
            continue;
        }
        break;
    }
    if s.is_empty() {
        return Ok(m);
    }
    if let Some(v) = s.strip_prefix('=') {
        m.default = Some(DefaultVal::Value(v.to_string()));
        return Ok(m);
    }
    if let Some(v) = s.strip_prefix('`') {
        let name = match v.strip_suffix('`') {
            Some(n) => n.to_string(),
            None => return Err(()),
        };
        if !defined_fns.iter().any(|f| f == &name) {
            return Err(());
        }
        m.default = Some(DefaultVal::Fn(name));
        return Ok(m);
    }
    if let Some(v) = s.strip_prefix('[') {
        let inner = match v.strip_suffix(']') {
            Some(i) => i.to_string(),
            None => return Err(()),
        };
        let (choice, def) = parse_choices(&inner, defined_fns)?;
        m.choice = Some(choice);
        m.default = def;
        return Ok(m);
    }
    Err(())
}

pub fn parse_choices(
    inner: &str,
    defined_fns: &Vec<String>,
) -> Result<(Choice, Option<DefaultVal>), ()> {
    if let Some(v) = inner.strip_prefix('?') {
        let v = match v.strip_prefix('`') {
            Some(x) => x,
            None => return Err(()),
        };
        let name = match v.strip_suffix('`') {
            Some(n) => n,
            None => return Err(()),
        };
        if !defined_fns.iter().any(|f| f == name) {
            return Err(());
        }
        return Ok((Choice::Fn(name.to_string(), false), None));
    }
    if let Some(v) = inner.strip_prefix('`') {
        let name = match v.strip_suffix('`') {
            Some(n) => n,
            None => return Err(()),
        };
        if !defined_fns.iter().any(|f| f == name) {
            return Err(());
        }
        return Ok((Choice::Fn(name.to_string(), true), None));
    }
    let mut def: Option<DefaultVal> = None;
    let body: Vec<String> = if let Some(v) = inner.strip_prefix('=') {
        let vals: Vec<&str> = v.split('|').collect();
        if vals.is_empty() {
            return Err(());
        }
        def = Some(DefaultVal::Value(vals[0].to_string()));
        vals.iter().map(|s| s.to_string()).collect()
    } else {
        inner.split('|').map(|s| s.to_string()).collect()
    };
    if body.is_empty() {
        return Err(());
    }
    Ok((Choice::Values(body), def))
}

pub fn parse_env_modifiers(
    rest: &str,
    defined_fns: &Vec<String>,
) -> Result<(bool, Option<DefaultVal>, Option<Choice>), ()> {
    let mut required = false;
    let mut s = rest;
    if let Some(r) = s.strip_prefix('!') {
        required = true;
        s = r;
    }
    if s.is_empty() {
        return Ok((required, None, None));
    }
    if let Some(v) = s.strip_prefix('=') {
        return Ok((required, Some(DefaultVal::Value(v.to_string())), None));
    }
    if let Some(v) = s.strip_prefix('`') {
        let name = match v.strip_suffix('`') {
            Some(n) => n.to_string(),
            None => return Err(()),
        };
        if !defined_fns.iter().any(|f| f == &name) {
            return Err(());
        }
        return Ok((required, Some(DefaultVal::Fn(name)), None));
    }
    if let Some(v) = s.strip_prefix('[') {
        let inner = match v.strip_suffix(']') {
            Some(i) => i.to_string(),
            None => return Err(()),
        };
        let (choice, def) = parse_choices(&inner, defined_fns)?;
        return Ok((required, def, Some(choice)));
    }
    Err(())
}

fn is_short_candidate(s: &str, t: (usize, usize)) -> bool {
    let tok = tok_at(s, t);
    let b = tok.as_bytes();
    if b.len() == 2 && (b[0] == b'-' || b[0] == b'+') {
        if let Some(c) = tok.chars().nth(1) {
            return c.is_alphanumeric() || c == '_';
        }
        return false;
    }
    if b.len() == 1 {
        let c = tok.chars().next().unwrap();
        if c == '=' || c == '<' || c == '>' {
            return false;
        }
        return true;
    }
    false
}

fn extract_short(s: &str, t: (usize, usize)) -> String {
    let tok = tok_at(s, t).to_string();
    if tok.starts_with('-') || tok.starts_with('+') {
        return tok;
    }
    let mut out = tok.clone();
    let idx = t.1;
    if idx < s.len() {
        let c = s[idx..].chars().next().unwrap();
        if c.is_whitespace() {
            out.push(c);
        }
    }
    out
}

struct LongParsed {
    symbol: char,
    double: bool,
    name: String,
    mods: String,
}

fn parse_long_token(tok: &str, is_arg: bool) -> Result<LongParsed, ()> {
    let b = tok.as_bytes();
    if b.is_empty() {
        return Err(());
    }
    let (symbol, double, rest_off) = if b[0] == b'-' && b.len() > 1 && b[1] == b'-' {
        ('-', true, 2)
    } else if b[0] == b'-' {
        ('-', false, 1)
    } else if b[0] == b'+' {
        ('+', false, 1)
    } else {
        return Err(());
    };
    let rest_str = &tok[rest_off..];
    let chars: Vec<char> = rest_str.chars().collect();
    let mut name = String::new();
    let mut i = 0usize;
    while i < chars.len() {
        let c = chars[i];
        if !is_arg_word_char(c) {
            break;
        }
        if !is_arg && (c == '-' || c == ':') {
            if i + 1 >= chars.len() || !is_arg_word_char(chars[i + 1]) {
                break;
            }
        }
        name.push(c);
        i += 1;
    }
    if name.is_empty() {
        return Err(());
    }
    let mods: String = chars[i..].iter().collect();
    Ok(LongParsed { symbol, double, name, mods })
}

fn parse_arg_name_token(tok: &str) -> Result<(String, String), ()> {
    let chars: Vec<char> = tok.chars().collect();
    let mut name = String::new();
    let mut i = 0usize;
    while i < chars.len() {
        if !is_arg_word_char(chars[i]) {
            break;
        }
        name.push(chars[i]);
        i += 1;
    }
    if name.is_empty() {
        return Err(());
    }
    Ok((name, chars[i..].iter().collect()))
}

fn env_of(tok: &str, id: &str) -> Option<String> {
    if tok == "$$" {
        return Some(id.to_uppercase());
    }
    if tok.starts_with('$') && tok.len() > 1 {
        let rest = &tok[1..];
        if !rest.is_empty() && rest.chars().all(|c| c.is_ascii_uppercase()) {
            return Some(rest.to_string());
        }
    }
    None
}

fn build_describe(s: &str, off: usize, extra: &[String]) -> String {
    let mut d = s[off..].trim().to_string();
    for e in extra {
        d.push('\n');
        d.push_str(e);
    }
    d
}

pub fn parse_option(
    text: &str,
    extra: &[String],
    line_no: usize,
    is_flag: bool,
    defined_fns: &Vec<String>,
) -> Result<Arg, ParseError> {
    let toks = tokenize_with_pos(text);
    if toks.is_empty() {
        return Err(ParseError::syntax(line_no));
    }
    let mut short: Option<String> = None;
    let mut li = 0usize;
    if toks.len() >= 2 && is_short_candidate(text, toks[0]) {
        short = Some(extract_short(text, toks[0]));
        li = 1;
    }
    let long_tok = tok_at(text, toks[li]).to_string();
    let l = match parse_long_token(&long_tok, false) {
        Ok(l) => l,
        Err(_) => return Err(ParseError::syntax(line_no)),
    };
    let id = if l.symbol == '+' {
        format!("plus_{}", l.name)
    } else {
        l.name.clone()
    };
    let mods = match parse_modifiers(&l.mods, defined_fns) {
        Ok(m) => m,
        Err(_) => return Err(ParseError::syntax(line_no)),
    };
    let long_name = format!("{}{}{}", l.symbol, if l.double { "-" } else { "" }, l.name);
    let end = toks[li].1;
    let after = &text[end..];
    let atoks = tokenize_with_pos(after);
    let mut env: Option<String> = None;
    let mut k = 0usize;
    if let Some(t0) = atoks.first() {
        if let Some(e) = env_of(tok_at(after, *t0), &id) {
            env = Some(e);
            k = 1;
        }
    }
    let mut notspecs: Vec<NotationSpec> = vec();
    while k < atoks.len() {
        let t = tok_at(after, atoks[k]);
        if t.starts_with('<') && t.ends_with('>') && t.len() >= 2 {
            notspecs.push(parse_notation(&t[1..t.len() - 1]));
            k += 1;
        } else {
            break;
        }
    }
    if notspecs.is_empty() && !is_flag {
        let derived = derive_notation(&l.name);
        notspecs.push(NotationSpec {
            text: derived,
            min: 1,
            max: 1,
            multiple: false,
            terminated: false,
        });
    }
    let multiple_occurs = mods.multiple_occurs;
    let terminated = mods.terminated;
    let not_multiple = notspecs.iter().any(|n| n.multiple);
    let multiple_values = multiple_occurs || terminated || not_multiple || notspecs.len() > 1;
    let min: u32 = notspecs.iter().map(|n| n.min).sum();
    let max: u32 = if notspecs.is_empty() { 0 } else { notspecs.iter().map(|n| n.max).sum() };
    let num_args = if is_flag { (0u32, 0u32) } else { (min, max) };
    let notations: Vec<String> = notspecs
        .iter()
        .map(|n| {
            if terminated && !n.terminated {
                format!("{}~", n.text)
            } else {
                n.text.clone()
            }
        })
        .collect();
    let describe = if k < atoks.len() {
        build_describe(after, atoks[k].0, extra)
    } else {
        build_describe(after, after.len(), extra)
    };
    Ok(Arg {
        id,
        long_name,
        short_name: short,
        describe,
        is_flag,
        notations,
        required: mods.required,
        multiple_values,
        multiple_occurs,
        num_args,
        delimiter: mods.delimiter,
        terminated,
        prefixed: mods.prefixed,
        assigned: mods.assigned,
        default: mods.default,
        choice: mods.choice,
        env,
        inherited: false,
    })
}

pub fn parse_positional(
    text: &str,
    extra: &[String],
    line_no: usize,
    defined_fns: &Vec<String>,
) -> Result<Positional, ParseError> {
    let toks = tokenize_with_pos(text);
    if toks.is_empty() {
        return Err(ParseError::syntax(line_no));
    }
    let t0 = tok_at(text, toks[0]).to_string();
    let (name, mods_str) = match parse_arg_name_token(&t0) {
        Ok(v) => v,
        Err(_) => return Err(ParseError::syntax(line_no)),
    };
    let mods = match parse_modifiers(&mods_str, defined_fns) {
        Ok(m) => m,
        Err(_) => return Err(ParseError::syntax(line_no)),
    };
    let end = toks[0].1;
    let after = &text[end..];
    let atoks = tokenize_with_pos(after);
    let mut env: Option<String> = None;
    let mut k = 0usize;
    if let Some(t) = atoks.first() {
        if let Some(e) = env_of(tok_at(after, *t), &name) {
            env = Some(e);
            k = 1;
        }
    }
    let mut notation: Option<String> = None;
    let mut not_multiple = false;
    let mut not_term = false;
    if k < atoks.len() {
        let t = tok_at(after, atoks[k]);
        if t.starts_with('<') && t.ends_with('>') && t.len() >= 2 {
            let spec = parse_notation(&t[1..t.len() - 1]);
            notation = Some(spec.text.clone());
            not_multiple = spec.multiple;
            not_term = spec.terminated;
            k += 1;
        }
    }
    let notation = match notation {
        Some(n) => n,
        None => derive_notation(&name),
    };
    let terminated = mods.terminated;
    let multiple = mods.multiple_occurs || terminated || not_multiple || not_term;
    let describe = if k < atoks.len() {
        build_describe(after, atoks[k].0, extra)
    } else {
        build_describe(after, after.len(), extra)
    };
    Ok(Positional {
        id: name,
        describe,
        notation,
        required: mods.required,
        multiple,
        delimiter: mods.delimiter,
        terminated,
        default: mods.default,
        choice: mods.choice,
        env,
    })
}

pub fn parse_env(
    text: &str,
    extra: &[String],
    line_no: usize,
    defined_fns: &Vec<String>,
) -> Result<Env, ParseError> {
    let toks = tokenize_with_pos(text);
    if toks.is_empty() {
        return Err(ParseError::syntax(line_no));
    }
    let t0 = tok_at(text, toks[0]).to_string();
    let (name, mods_str) = match parse_arg_name_token(&t0) {
        Ok(v) => v,
        Err(_) => return Err(ParseError::syntax(line_no)),
    };
    let (required, default, choice) = match parse_env_modifiers(&mods_str, defined_fns) {
        Ok(v) => v,
        Err(_) => return Err(ParseError::syntax(line_no)),
    };
    let end = toks[0].1;
    let after = &text[end..];
    let describe = build_describe(after, 0, extra);
    Ok(Env {
        id: name,
        describe,
        required,
        default,
        choice,
        inherited: false,
    })
}
