    pub version: Option<String>,
    pub dotenv: Option<Option<String>>,
    pub require_tools: Option<String>,
    pub default_subcommand: Option<Option<String>>,
    pub inherit_flag_options: bool,
    pub combine_shorts: bool,
    pub symbol: Option<String>,
    pub others: Vec<(String, Option<String>)>,
}

pub fn merge_meta(dst: &mut Meta, src: &Meta) {
    if src.version.is_some() {
        dst.version = src.version.clone();
    }
    if src.dotenv.is_some() {
        dst.dotenv = src.dotenv.clone();
    }
    if src.require_tools.is_some() {
        let cur = dst.require_tools.clone().unwrap_or_default();
        let add = src.require_tools.clone().unwrap();
        let combined = if cur.is_empty() { add } else { format!("{},{}", cur, add) };
        dst.require_tools = Some(combined);
    }
    if src.default_subcommand.is_some() {
        dst.default_subcommand = src.default_subcommand.clone();
    }
    dst.inherit_flag_options |= src.inherit_flag_options;
    dst.combine_shorts |= src.combine_shorts;
    if src.symbol.is_some() {
        dst.symbol = src.symbol.clone();
    }
    for (k, v) in &src.others {
        if !dst.others.iter().any(|(kk, _)| kk == k) {
            dst.others.push((k.clone(), v.clone()));
        }
    }
}

