use crate::model::*;

pub fn wrap(text: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return text.split('\n').map(|s| s.to_string()).collect();
    }
    let mut out: Vec<String> = vec![];
    for line in text.split('\n') {
        if line.is_empty() {
            out.push(String::new());
            continue;
        }
        let mut cur = String::new();
        let mut cur_len = 0usize;
        let mut first_word = true;
        for w in line.split_whitespace() {
            let wl = w.chars().count();
            if cur_len == 0 {
                if wl <= width {
                    cur = w.to_string();
                    cur_len = wl;
                } else {
                    // break the word
                    let chars: Vec<char> = w.chars().collect();
                    let mut i = 0;
                    while i < chars.len() {
                        let take = std::cmp::min(width, chars.len() - i);
                        out.push(chars[i..i + take].iter().collect::<String>());
                        i += take;
                    }
                }
                first_word = false;
                let _ = first_word;
                continue;
            }
            if cur_len + 1 + wl <= width {
                cur.push(' ');
                cur.push_str(w);
                cur_len += 1 + wl;
            } else {
                out.push(cur.clone());
                if wl <= width {
                    cur = w.to_string();
                    cur_len = wl;
                } else {
                    let chars: Vec<char> = w.chars().collect();
                    let mut i = 0;
                    while i < chars.len() {
                        let take = std::cmp::min(width, chars.len() - i);
