    }
}

fn quote_block(body: &str) -> String {
    format!("command cat >&2 <<-'EOF' \n{}\nEOF\n", body)
}

pub fn render_notations(a: &Arg) -> String {
    if a.notations.is_empty() {
        return String::new();
    }
    if a.notations.len() == 1 && a.num_args.0 == 1 && a.num_args.1 == 1 {
        let n = &a.notations[0];
        if a.assigned {
            return format!("=<{}>", n);
        }
        if a.multiple_occurs {
            return if a.required {
                format!("<{}>...", n)
            } else {
                format!("[{}]...", n)
            };
        }
        return format!("<{}>", n);
    }
    let parts: Vec<String> = a.notations.iter().map(|n| format!("<{}>", n)).collect();
    let joined = parts.join(" ");
    if a.assigned {
        format!("={}", joined)
    } else {
        joined
    }
}

pub fn render_positional_notation(p: &Positional) -> String {
    if p.multiple {
        if p.required {
            format!("<{}>...", p.notation)
        } else {
            format!("[{}]...", p.notation)
        }
    } else if p.required {
        format!("<{}>", p.notation)
    } else {
        format!("[{}]", p.notation)
    }
}

fn long_rendered(long: &str) -> String {
    if long.starts_with("--") {
        long.to_string()
    } else {
        format!(" {}", long)
    }
}

fn arg_name_part(a: &Arg) -> String {
    let lr = long_rendered(&a.long_name);
    let base = match &a.short_name {
        Some(s) => format!("{}, {}", s, lr),
        None => format!("    {}", lr),
    };
    let nn = render_notations(a);
    if nn.is_empty() {
        base
    } else if a.assigned {
        format!("{}{}", base, nn)
    } else {
        format!("{} {}", base, nn)
    }
}

fn extra_info(a: &Arg) -> String {
    let mut parts: Vec<String> = vec![];
    if let Some(Choice::Values(v)) = &a.choice {
        if !v.is_empty() {
            parts.push(format!("[possible values: {}]", v.join(", ")));
        }
    }
    if let Some(DefaultVal::Value(v)) = &a.default {
        parts.push(format!("[default: {}]", v));
    }
    parts.join(" ")
}

fn arg_describe_text(a: &Arg) -> String {
    let d = a.describe.clone();
    let e = extra_info(a);
    if e.is_empty() {
        d
    } else if d.is_empty() {
        e
    } else {
        format!("{} {}", d, e)
    }
}

fn indent_lines(lines: &[String], n: usize) -> Vec<String> {
    lines.iter().map(|l| format!("{}{}", " ".repeat(n), l)).collect()
}

pub fn build_help(cmd: &Cmd, path: &str, width: Option<usize>) -> String {
    let mut out: Vec<String> = vec![];
    // describe
    if !cmd.describe.is_empty() {
        let wrapped = match width {
            Some(w) => wrap(&cmd.describe, w),
            None => cmd.describe.split('\n').map(|s| s.to_string()).collect(),
        };
        out.extend(wrapped);
        out.push(String::new());
    }
    // usage
    out.push(format!("USAGE: {}", usage_line(cmd, path)));
    out.push(String::new());
    // args
    if !cmd.positionals.is_empty() {
        out.push("ARGS:".to_string());
        let long_mode = cmd.positionals.iter().any(|p| p.describe.contains('\n'));
        let entries: Vec<(String, String)> = cmd
            .positionals
            .iter()
            .map(|p| (render_positional_notation(p), p.describe.clone()))
            .collect();
        if long_mode {
            for (name, d) in &entries {
                out.push(format!("  {}", name));
                if !d.is_empty() {
                    let lines = match width {
                        Some(w) if w > 10 => wrap(d, w - 10),
                        _ => d.split('\n').map(|s| s.to_string()).collect(),
                    };
                    out.extend(indent_lines(&lines, 10));
                }
                out.push(String::new());
            }
        } else {
            let mut w = 0usize;
            for (name, _) in &entries {
                let l = name.chars().count() + 2;
                if l > w {
                    w = l;
                }
            }
            let total = 2 + w;
            for (name, d) in &entries {
                let mut line = format!("  {}", name);
                if line.chars().count() < total {
                    line.push_str(&" ".repeat(total - line.chars().count()));
                }
                if d.is_empty() {
                    out.push(line);
                } else {
                    match width {
                        Some(w) if w > total => {
                            let lines = wrap(d, w - total);
                            if let Some(f) = lines.first() {
                                out.push(format!("{}{}", line, f));
                            }
                            for l in lines.iter().skip(1) {
                                out.push(format!("{}{}", " ".repeat(total), l));
                            }
                        }
                        _ => out.push(format!("{}{}", line, d)),
                    }
                }
            }
            out.push(String::new());
        }
    }
    // options
    if !cmd.args.is_empty() {
        out.push("OPTIONS:".to_string());
        let long_mode = cmd.args.iter().any(|a| arg_describe_text(a).contains('\n'));
        let entries: Vec<(String, String)> = cmd
            .args
            .iter()
            .map(|a| (arg_name_part(a), arg_describe_text(a)))
            .collect();
        if long_mode {
            for (name, d) in &entries {
                out.push(format!("  {}", name));
                if !d.is_empty() {
                    let lines = match width {
                        Some(w) if w > 10 => wrap(d, w - 10),
                        _ => d.split('\n').map(|s| s.to_string()).collect(),
                    };
                    out.extend(indent_lines(&lines, 10));
                }
                out.push(String::new());
            }
        } else {
            let mut w = 0usize;
            for (name, _) in &entries {
                let l = name.chars().count() + 2;
                if l > w {
                    w = l;
                }
            }
            let total = 2 + w;
            for (name, d) in &entries {
                let mut line = format!("  {}", name);
                if line.chars().count() < total {
                    line.push_str(&" ".repeat(total - line.chars().count()));
                }
                if d.is_empty() {
                    out.push(line);
                } else {
                    match width {
                        Some(w) if w > total => {
                            let lines = wrap(d, w - total);
                            if let Some(f) = lines.first() {
                                out.push(format!("{}{}", line, f));
                            }
                            for l in lines.iter().skip(1) {
                                out.push(format!("{}{}", " ".repeat(total), l));
                            }
                        }
                        _ => out.push(format!("{}{}", line, d)),
                    }
                }
            }
            out.push(String::new());
        }
    }
    // commands
    if !cmd.subcommands.is_empty() {
        out.push("COMMANDS:".to_string());
        let entries: Vec<(String, String)> = cmd
            .subcommands
            .iter()
            .map(|s| {
                let d = match &s.describe {
                    d if d.is_empty() => String::new(),
                    d => d.split('\n').next().unwrap_or("").to_string(),
                };
                let d = if cmd.default_subcommand_name().as_deref() == Some(s.name.as_str()) {
                    if d.is_empty() {
                        "[default]".to_string()
                    } else {
                        format!("{} [default]", d)
                    }
                } else {
                    d
                };
                let aliases = if s.aliases.is_empty() {
                    String::new()
                } else {
                    format!(" [aliases: {}]", s.aliases.join(", "))
                };
                let d = format!("{}{}", d, aliases);
                (s.name.clone(), d)
            })
            .collect();
        let mut w = 0usize;
        for (name, _) in &entries {
            let l = name.chars().count() + 2;
            if l > w {
                w = l;
            }
        }
        let total = 2 + w;
        for (name, d) in &entries {
            let mut line = format!("  {}", name);
            if line.chars().count() < total {
                line.push_str(&" ".repeat(total - line.chars().count()));
            }
            if d.is_empty() {
                out.push(line);
            } else {
                match width {
                    Some(w) if w > total => {
                        let lines = wrap(d, w - total);
                        if let Some(f) = lines.first() {
                            out.push(format!("{}{}", line, f));
                        }
                        for l in lines.iter().skip(1) {
                            out.push(format!("{}{}", " ".repeat(total), l));
                        }
                    }
                    _ => out.push(format!("{}{}", line, d)),
                }
            }
        }
        out.push(String::new());
    }
    let body = out.join("\n");
    quote_block(&body)
}

pub fn usage_line(cmd: &Cmd, path: &str) -> String {
    let mut parts: Vec<String> = vec![path.to_string()];
    if cmd.has_options() {
        parts.push("[OPTIONS]".to_string());
    }
    for a in cmd.args.iter() {
        if a.required && a.id != "help" && a.id != "version" {
            let n = render_notations(a);
            if n.is_empty() {
                parts.push(a.long_name.clone());
            } else {
                parts.push(format!("{}{}", a.long_name, n));
            }
        }
    }
    if cmd.subcommands.is_empty() {
        for p in &cmd.positionals {
            parts.push(render_positional_notation(p));
        }
    } else {
        parts.push("<COMMAND>".to_string());
    }
    parts.join(" ")
}
