    let last = matches.len() - 1;
    if matches[last].positionals.len() == 1 && matches[last].positionals[0] == "help" {
        return Err(Fail::Help(path));
    }
    Ok(matches)
}

fn cmd_path(root: &Cmd, path: &[usize]) -> Vec<String> {
    let mut out = vec![];
    let mut c = root;
    for i in path {
        c = &c.subcommands[*i];
        out.push(c.name.clone());
    }
    out
}

enum OptRes {
    Consumed(usize),
}

fn try_option(
    cmd: &Cmd,
    a: &str,
    args: &[String],
    i: usize,
    signs: &str,
    vals: &mut Vec<(String, Vec<String>)>,
) -> Option<OptRes> {
    let (name, eqval) = if let Some(p) = a.find('=') {
        (&a[..p], Some(a[p + 1..].to_string()))
    } else {
        (a, None)
    };
    // assigned options require '='
    let mut oi: Option<usize> = None;
    if name.starts_with("--") || name.starts_with('+') {
        oi = find_option_long(cmd, name);
    } else if name.starts_with('-') && name.len() >= 2 {
        oi = find_option_short(cmd, name).or_else(|| find_option_long(cmd, name));
    }
    let oi = oi?;
    let opt = cmd.args[oi].clone();
    if eqval.is_some() {
        if opt.is_flag {
            return None;
        }
    } else if opt.assigned {
        // assigned requires '='
        return Some(OptRes::Consumed(consume_values(
            cmd, &opt, name, 0, &[], vals, true,
        )));
    }
    if opt.is_flag {
        if eqval.is_some() {
            return None;
        }
        // count occurrences
        let mut found = false;
        for v in vals.iter_mut() {
            if v.0 == opt.id {
                v.1.push("1".to_string());
                found = true;
            }
        }
        if !found {
            vals.push((opt.id.clone(), vec!["1".to_string()]));
        }
        return Some(OptRes::Consumed(1));
    }
    // take values
    let (min, max) = opt.num_args;
    if min == 0 && max == 0 {
        return Some(OptRes::Consumed(1));
    }
    let mut values: Vec<String> = vec![];
    if let Some(v) = eqval {
        values.push(v);
    } else {
        let mut j = i + 1;
        while j < args.len() && (values.len() as u32) < max {
            let t = &args[j];
            if maybe_flag_option(signs, t) && t.chars().count() > 1 {
                break;
            }
            values.push(t.clone());
            j += 1;
        }
    }
    if (values.len() as u32) < min {
        let param = format!("{} {}", opt.long_name, render_notations(&opt));
        return Some(OptRes::Consumed(consume_error(&param)));
    }
    let n = 1 + values.len();
    // delimiter split
    let mut final_values = values.clone();
    if let Some(d) = opt.delimiter {
        let mut nv: Vec<String> = vec![];
        for v in &values {
            for p in v.split(d) {
                nv.push(p.to_string());
            }
        }
        final_values = nv;
    }
    vals.push((opt.id.clone(), final_values));
    Some(OptRes::Consumed(n))
}

fn consume_error(_param: &str) -> usize {
    0
}

fn consume_values(
    _cmd: &Cmd,
    _opt: &Arg,
    _name: &str,
    _n: usize,
    _args: &[String],
    _vals: &mut Vec<(String, Vec<String>)>,
    _err: bool,
) -> usize {
    0
}

fn try_combined(cmd: &Cmd, a: &str, vals: &mut Vec<(String, Vec<String>)>) -> Option<usize> {
    let chars: Vec<char> = a.chars().skip(1).collect();
    for c in &chars {
        let s = format!("-{}", c);
        let oi = find_option_short(cmd, &s)?;
        let opt = cmd.args[oi].clone();
        if !opt.is_flag {
            return None;
        }
        let mut found = false;
        for v in vals.iter_mut() {
            if v.0 == opt.id {
                v.1.push("1".to_string());
                found = true;
            }
        }
        if !found {
            vals.push((opt.id.clone(), vec!["1".to_string()]));
        }
    }
    Some(1)
}
