// ---------- positional matching ----------
pub fn match_positionals(
    args: &[String],
    specs: &[bool],
    dash: Option<usize>,
) -> Result<Vec<(usize, usize)>, Fail> {
    if args.is_empty() {
        return Ok(vec![]);
    }
    let params_len = specs.len();
    let mut arg_index = 0usize;
    let mut param_index = 0usize;
    let mut values: Vec<(usize, usize)> = vec![];
    while param_index < params_len && arg_index < args.len() {
        let takes;
        if specs[param_index] {
            if param_index == 0
                && dash.unwrap_or(0) > 0
                && params_len == 2
                && specs[1]
            {
                takes = dash.unwrap();
            } else {
                let arg_diff = args.len() - arg_index;
                let param_diff = params_len - param_index;
                takes = if arg_diff > param_diff { arg_diff - param_diff + 1 } else { 1 };
            }
        } else {
            takes = 1;
        }
        values.push((arg_index, takes));
        arg_index += takes;
        param_index += 1;
    }
    if arg_index < args.len() {
        values.push((arg_index, args.len() - arg_index));
    }
    if params_len > 0 && values.len() > params_len {
        let index = values[params_len].0;
        return Err(Fail::Msg(format!(
            "error: unexpected argument `{}` found",
            args[index]
        )));
    }
    Ok(values)
}

// ---------- value resolution ----------
pub fn resolve_cmd(
    cmd: &Cmd,
    vals: &mut Vec<(String, Vec<String>)>,
    positionals: &mut Vec<(usize, usize)>,
    pos_args: &[String],
) -> Result<(), Fail> {
    // options
    for a in cmd.args.iter() {
        let mut values = match vals.iter().find(|(k, _)| k == &a.id) {
            Some(v) => v.1.clone(),
            None => vec![],
        };
        if values.is_empty() {
            if let Some(env_name) = &a.env {
                if let Ok(v) = std::env::var(env_name) {
                    if a.is_flag {
                        if v == "1" || v == "true" {
                            values.push("1".to_string());
                        } else if v != "0" && v != "false" {
                            return Err(Fail::Msg(format!(
                                "error: environment variable `{}` has invalid value for param '--{}'",
                                env_name,
                                a.id.trim_start_matches("plus_")
                            )));
                        }
                    } else {
                        values.push(v);
                    }
                }
            }
        }
        if values.is_empty() {
            if let Some(d) = &a.default {
                match d {
                    DefaultVal::Value(v) => values.push(v.clone()),
                    DefaultVal::Fn(f) => values.push(format!("`{}`", f)),
                }
            }
        }
        if let Some(c) = &a.choice {
            match c {
                Choice::Values(vs) => {
                    for v in &values {
                        if !vs.contains(v) {
                            return Err(Fail::Msg(format!(
                                "error: invalid value `{}` for `{}`\n  [possible values: {}]",
                                v,
                                render_notations(a),
                                vs.join(", ")
                            )));
                        }
                    }
                }
                Choice::Fn(_, validate) => {
                    if *validate && !values.is_empty() {
                        return Err(Fail::Msg(format!(
                            "error: invalid value `{}` for `{}`\n  [possible values: ]",
                            values[0],
                            render_notations(a)
                        )));
                    }
                }
            }
        }
        if values.is_empty() && a.required {
            return Ok(());
        }
        set_val(vals, &a.id, values);
    }
    Ok(())
}

pub fn render_help_for(root: &Cmd, path: &[usize]) -> String {
    let mut cmd = root.clone();
    let mut names: Vec<String> = vec![];
    for i in path {
        cmd = cmd.subcommands[*i].clone();
        names.push(cmd.name.clone());
    }
    let p = if names.is_empty() {
        cmd.name.clone()
    } else {
        format!("{} {}", cmd.name, names.join(" "))
    };
    finalize_cmd(&mut cmd, cmd.is_root);
    let width = get_width();
    build_help(&cmd, &p, width)
}

