        for e in cmd.envs.iter() {
            if let Some(d) = &e.default {
                if std::env::var(&e.id).is_err() {
                    let v = match d {
                        DefaultVal::Value(v) => shell_quote(v),
                        DefaultVal::Fn(f) => format!("`{}`", f),
                    };
                    printed.push(format!("export {}={}", e.id, v));
                    defs.push(format!("export {}={}", e.id, v));
                }
            }
        }
    }
    // param values
    for (cmd, resolved, pos_vals) in &all {
        for (id, values) in resolved {
            let line = emit_value_line(id, values);
            if !line.is_empty() {
                printed.push(line.clone());
                defs.push(line);
            }
        }
        for (i, values) in pos_vals {
            let p = &cmd.positionals[*i];
            let line = emit_value_line(&p.id, values);
            if !line.is_empty() {
                printed.push(line.clone());
                defs.push(line);
            }
        }
    }
    let leaf = &matches[matches.len() - 1];
    let leaf_cmd = &all[all.len() - 1].0;
    let all_args: Vec<String> = {
        let mut v = vec![stem.to_string()];
        v.extend(args.iter().cloned());
        v
    };
    let args_line = format!("argc__args=( {} )", shell_quote_list(&all_args));
    printed.push(args_line.clone());
    defs.push(args_line);
    let fn_name = leaf_cmd.command_fn.clone();
    if let Some(f) = &fn_name {
        let l = format!("argc__fn={}", f);
        printed.push(l.clone());
        defs.push(l);
    }
    let pos_line = format!("argc__positionals=( {} )", shell_quote_list(&leaf.positionals));
    printed.push(pos_line.clone());
    defs.push(pos_line);
    // require tools
    let mut tools: Vec<String> = vec![];
    for (cmd, _, _) in &all {
        tools.extend(cmd.tools());
    }
    if !tools.is_empty() {
        printed.push(String::new());
        printed.push(REQUIRE_TOOLS_FN.to_string());
        printed.push(format!(
            "_argc_require_tools {}",
            shell_quote_list(&tools)
        ));
        printed.push(String::new());
    }
    // hooks
    let has_before = ps.functions.iter().any(|f| f == "_argc_before");
    let has_after = ps.functions.iter().any(|f| f == "_argc_after");
    let mut hooks: Vec<String> = vec![];
    if has_before {
        hooks.push("_argc_before".to_string());
    }
    if has_after {
        hooks.push("_argc_after".to_string());
    }
    let call = match &fn_name {
        Some(f) => {
            let mut c = f.clone();
            if !leaf.positionals.is_empty() {
                c.push(' ');
                c.push_str(&shell_quote_list(&leaf.positionals));
            }
            Some(c)
        }
        None => None,
    };
    if let Some(c) = &call {
        for h in &hooks {
            defs.push(format!("{};", h));
        }
    }
    let joined: String = defs.iter().map(|d| format!("{};", d)).collect();
    let mut out: Vec<String> = vec![];
    out.push(format!("export ARGC_VARS={}", base64_encode(joined.as_bytes())));
    out.extend(printed);
    if let Some(c) = &call {
        out.extend(hooks.clone());
        out.push(c.clone());
        if has_after {
            out.push("_argc_after".to_string());
        }
    }
    format!("{}\n", out.join("\n"))
}

fn find_dotenv(cmd: &Cmd) -> Option<Option<String>> {
    if cmd.meta.dotenv.is_some() {
        return cmd.meta.dotenv.clone();
    }
    for s in &cmd.subcommands {
        if let Some(d) = find_dotenv(s) {
            return Some(d);
        }
    }
    None
}
RSEOF
echo ok"}

