use crate::model::*;
use crate::parser::*;
use crate::eval::*;
use crate::help::*;

pub enum LoadFail {
    Io(String, String), // top message, cause
    Parse(String),
}

pub fn stem_of(path: &str) -> String {
    let f = Path::new(path)
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| path.to_string());
    match f.strip_suffix(".sh") {
        Some(s) => s.to_string(),
        None => f,
    }
}

use std::path::Path;

pub fn load_script(path: &str) -> Result<ParsedScript, LoadFail> {
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => {
            return Err(LoadFail::Io(
                format!("Failed to load script at '{}'", path),
                e.to_string(),
            ))
        }
    };
    let stem = stem_of(path);
    match parse_script(&content, &stem) {
        Ok(p) => Ok(p),
        Err(e) => Err(LoadFail::Parse(e.message)),
    }
}

pub fn do_eval(args: &[String]) {
    if args.is_empty() {
        println!("echo 'Error: No script file provided'");
        println!("exit 1");
        return;
    }
    let path = &args[0];
    let ps = match load_script(path) {
        Ok(p) => p,
        Err(LoadFail::Io(top, _cause)) => {
            let q = top.replace('\'', "'\\''");
            println!("echo 'Error: {}'", q);
            println!("exit 1");
            return;
        }
        Err(LoadFail::Parse(m)) => {
            let q = m.replace('\'', "'\\''");
            println!("echo 'Error: {}'", q);
            println!("exit 1");
            return;
        }
    };
    let stem = stem_of(path);
    let is_argcfile = stem == "Argcfile";
    let cwd = std::env::current_dir()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_default();
    let rest = &args[1..];
    let out = generate_eval(&ps, &stem, rest, is_argcfile, &cwd);
    print!("{}", out);
}

pub fn do_run(args: &[String]) {
    if args.is_empty() {
        eprintln!("No script file provided");
        std::process::exit(1);
    }
    let path = &args[0];
    if let Err(e) = load_script(path) {
        report_load(&e);
        std::process::exit(1);
    }
    let shell = match crate::main::find_shell() {
        Some(s) => s,
        None => {
            eprintln!("Shell not found");
            std::process::exit(1);
        }
    };
    let mut cmd = std::process::Command::new(shell);
    cmd.arg(path);
    for a in &args[1..] {
        cmd.arg(a);
    }
    let code = cmd.status().map(|s| s.code().unwrap_or(1)).unwrap_or(1);
    std::process::exit(code);
}

pub fn report_load(e: &LoadFail) {
    match e {
        LoadFail::Io(top, cause) => {
            eprintln!("{}\n\nCaused by:\n    {}", top, cause);
        }
        LoadFail::Parse(m) => {
            eprintln!("{}", m);
        }
    }
}

pub fn do_export(args: &[String]) {
    if args.is_empty() {
        eprintln!("No script file provided");
        std::process::exit(1);
    }
    let ps = match load_script(&args[0]) {
        Ok(p) => p,
        Err(e) => {
            report_load(&e);
            std::process::exit(1);
        }
    };
    crate::export::print_export(&ps);
}

pub fn do_mangen(args: &[String]) {
    if args.len() < 2 {
        eprintln!("No script file provided");
        std::process::exit(1);
    }
    let ps = match load_script(&args[0]) {
        Ok(p) => p,
        Err(e) => {
            report_load(&e);
            std::process::exit(1);
        }
    };
    crate::mangen::generate(&ps, &args[1]);
}

pub fn do_create(args: &[String]) {
    let cwd = std::env::current_dir().unwrap();
    let p = cwd.join("Argcfile.sh");
    if p.exists() {
        eprintln!("Already exist {}", p.to_string_lossy());
        std::process::exit(1);
    }
    let mut content = String::from("#!/usr/bin/env bash\n\nset -e\n");
    let recipes: Vec<String> = if args.is_empty() {
        vec!["build".to_string(), "test".to_string(), "lint".to_string()]
    } else {
        args.to_vec()
    };
    for r in recipes {
        content.push_str(&format!(
            "\n# @cmd\n{}() {{\n    echo TODO {}\n}}\n",
            r, r
        ));
    }
    content.push_str("\n# See more details at https://github.com/sigoden/argc\neval \"$(argc --argc-eval \"$0\" \"$@\")\"\n");
    std::fs::write(&p, content).unwrap();
    println!("Argcfile.sh has been successfully created.");
}

pub fn run_argcfile(args: &[String]) {
    let path = match crate::main::find_argcfile() {
        Some(p) => p,
        None => {
            println!("Argcfile not found, try `argc --argc-help` for help.");
            std::process::exit(1);
        }
    };
    let shell = match crate::main::find_shell() {
        Some(s) => s,
        None => {
            eprintln!("Shell not found");
            std::process::exit(1);
        }
    };
    let mut cmd = std::process::Command::new(shell);
    cmd.arg(&path);
    for a in args {
        cmd.arg(a);
    }
    let code = cmd.status().map(|s| s.code().unwrap_or(1)).unwrap_or(1);
    std::process::exit(code);
}

pub fn do_parallel(args: &[String]) {
    if args.is_empty() {
        eprintln!("Usage: argc --argc-parallel <SCRIPT> <ARGS>...");
        std::process::exit(1);
    }
    let script = &args[0];
    let ps = match load_script(script) {
        Ok(p) => p,
        Err(e) => {
            report_load(&e);
            std::process::exit(1);
        }
    };
    let content = match std::fs::read_to_string(script) {
        Ok(c) => c,
        Err(_) => return,
    };
    if !content.contains("argc --argc-eval") {
        eprintln!("Parallel only available for argc based scripts.");
        std::process::exit(1);
    }
    let rest = &args[1..];
    let mut groups: Vec<Vec<String>> = vec![];
    let mut cur: Vec<String> = vec![];
    for a in rest {
        if a == ":::" {
            groups.push(std::mem::take(&mut cur));
        } else {
            cur.push(a.clone());
        }
    }
    groups.push(cur);
    let defs = std::env::var("ARGC_VARS").unwrap_or_default();
    let mut children = vec![];
    for g in &groups {
        if g.is_empty() {
            continue;
        }
        let tmpdir = std::env::temp_dir().join(format!(
            "argc-parallel-{}-{}",
            std::process::id(),
            children.len()
        ));
        let _ = std::fs::create_dir_all(&tmpdir);
        let name = Path::new(script)
            .file_name()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| "script.sh".to_string());
        let job = tmpdir.join(&name);
        let mut out = String::new();
        out.push_str(&format!("eval \"{}\"\n", crate::eval::shell_quote(&{
            let decoded = crate::eval::base64_decode(&defs)
                .map(|b| String::from_utf8_lossy(&b).to_string())
                .unwrap_or_default();
            decoded
        })));
        // content with the eval line replaced
        let mut lines: Vec<&str> = content.split('\n').collect();
        // find the eval line
        let mut replaced = false;
        for l in lines.iter_mut() {
            if !replaced && l.contains("argc --argc-eval") {
                let mut call = crate::eval::shell_quote(&g[0]);
                if g.len() > 1 {
                    call.push(' ');
                    call.push_str(&crate::eval::shell_quote_list(&g[1..]));
                }
                *l = &call;
                replaced = true;
            }
        }
        out.push_str(&lines.join("\n"));
        let _ = std::fs::write(&job, out);
        let shell = crate::main::find_shell().unwrap();
        let mut cmd = std::process::Command::new(shell);
        cmd.arg(&job);
        cmd.env("ARGC_PARALLEL", "1");
