pub fn build_help(cmd: &Cmd, path: &str, width: Option<usize>) -> String {""","""    // environments
    if !cmd.envs.is_empty() {
        out.push("ENVIRONMENTS:".to_string());
        let long_mode = cmd.envs.iter().any(|e| env_describe_text(e).contains('\\n'));
        let entries: Vec<(String, String)> = cmd
            .envs
            .iter()
            .map(|e| {
                let mut n = e.id.clone();
                if e.required {
                    n.push('*');
                }
                (n, env_describe_text(e))
            })
            .collect();
        let mut w = 0usize;
        for (name, _) in &entries {
            let l = name.chars().count() + 2;
            if l > w {
                w = l;
            }
        }
        let total = 2 + w;
        for (name, d) in &entries {
            if d.is_empty() {
                out.push(format!("  {}", name));
                continue;
            }
            let mut line = format!("  {}", name);
            if line.chars().count() < total {
                line.push_str(&" ".repeat(total - line.chars().count()));
            }
            {
                match width {
                    Some(w) if w > total => {
                        let lines = wrap(d, w - total);
                        if let Some(f) = lines.first() {
                            out.push(format!("{}{}", line, f));
                        }
                        for l in lines.iter().skip(1) {
                            out.push(format!("{}{}", " ".repeat(total), l));
                        }
                    }
                    _ => out.push(format!("{}{}", line, d)),
                }
            }
        }
        out.push(String::new());
    }
    out.join("\\n")
}

