    let mut path: Vec<usize> = vec![];
    let mut started = false;
    let mut broken = false;
    let mut after_dash = false;
    let mut help: Option<Vec<usize>> = None;
    let mut version: Option<Vec<usize>> = None;
    let mut i = 0usize;
    while i < args.len() {
        let a = &args[i];
        if after_dash {
            i += 1;
            continue;
        }
        if a == "--" {
            after_dash = true;
            i += 1;
            continue;
        }
        let cur = cmd_at(root, &path);
        if !started && find_sub(&cur, a).is_some() {
            path.push(find_sub(&cur, a).unwrap());
            started = true;
            i += 1;
            continue;
        }
        if a == "--help" || a == "-h" {
            if !broken && help.is_none() && version.is_none() {
                help = Some(path.clone());
            }
            i += 1;
            continue;
        }
        if a == "--version" || a == "-V" {
            let has_v = cur.is_root || cur.meta.version.is_some();
            if !broken && has_v && help.is_none() && version.is_none() {
                version = Some(path.clone());
            }
            i += 1;
            continue;
        }
        if a.starts_with('-') || a.starts_with('+') {
            let (name, eqval) = match a.find('=') {
                Some(p) => (a[..p].to_string(), true),
                None => (a.clone(), false),
            };
            let oi = if name.starts_with("--") || (name.starts_with('+') && name.len() > 1) {
                find_option_long(&cur, &name)
            } else if name.starts_with('-') && name.len() >= 2 {
                find_option_short(&cur, &name).or_else(|| find_option_long(&cur, &name))
            } else {
                None
            };
            match oi {
                Some(o) => {
                    let opt = cur.args[o].clone();
                    if opt.is_flag || eqval {
                        i += 1;
                        continue;
                    }
                    let (_min, max) = opt.num_args;
                    if max == 0 {
                        i += 1;
                        continue;
                    }
                    let mut n = 1usize;
                    let mut j = i + 1;
                    while j < args.len() && n < max as usize {
                        if maybe_flag_option(&cmd_signs(&cur), &args[j]) && args[j].chars().count() > 1 {
                            break;
                        }
                        n += 1;
                        j += 1;
                    }
                    i += n;
                    continue;
                }
                None => {
                    broken = true;
                    i += 1;
                    continue;
                }
            }
        }
        started = true;
        i += 1;
    }
    if let Some(p) = help {
        return Some(Fail::Help(p));
    }
    if let Some(_p) = version {
        let names = cmd_path_names(root, &path);
        let mut cmd = cmd_at(root, &path);
        let name = if path.is_empty() {
            root.name.clone()
        } else {
            format!("{}-{}", root.name, names.join("-"))
        };
        let v = cmd.version.clone().unwrap_or_else(|| "0.0.0".to_string());
        return Some(Fail::VersionText(format!("{} {}", name, v)));
    }
    None
}

