{"command": "cat > /tmp/dev/argc/src/export.rs <<'RSEOF'
use crate::model::*;

fn esc(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn opt_str(v: &Option<String>) -> String {
    match v {
        Some(s) => esc(s),
        None => "null".to_string(),
    }
}

fn choice_json(c: &Option<Choice>) -> String {
    match c {
        None => "null".to_string(),
        Some(Choice::Values(v)) => {
            let items: Vec<String> = v.iter().map(|s| esc(s)).collect();
            format!("{{\n        \"type\": \"Values\",\n        \"data\": [\n          {}\n        ]\n      }}", items.join(",\n          "))
        }
        Some(Choice::Fn(f, validate)) => {
            format!("{{\n        \"type\": \"Fn\",\n        \"data\": [\n          {},\n          {}\n        ]\n      }}", esc(f), validate)
        }
    }
}

fn default_json(d: &Option<DefaultVal>) -> String {
    match d {
        None => "null".to_string(),
        Some(DefaultVal::Value(v)) => {
            format!("{{\n        \"type\": \"Value\",\n        \"value\": {}\n      }}", esc(v))
        }
        Some(DefaultVal::Fn(f)) => {
            format!("{{\n        \"type\": \"Fn\",\n        \"value\": {}\n      }}", esc(f))
        }
    }
}

fn arg_json(a: &Arg) -> String {
    let sn = match &a.short_name {
        Some(s) => esc(s),
        None => "null".to_string(),
    };
    let nots: Vec<String> = a.notations.iter().map(|s| esc(s)).collect();
    format!(
        "    {{\n      \"id\": {},\n      \"long_name\": {},\n      \"short_name\": {},\n      \"describe\": {},\n      \"flag\": {},\n      \"notations\": {},\n      \"required\": {},\n      \"multiple_values\": {},\n      \"multiple_occurs\": {},\n      \"num_args\": [\n        {},\n        {}\n      ],\n      \"delimiter\": {},\n      \"terminated\": {},\n      \"prefixed\": {},\n      \"assigned\": {},\n      \"default\": {},\n      \"choice\": {},\n      \"env\": {},\n      \"inherited\": {}\n    }}",
        esc(&a.id),
        esc(&a.long_name),
        sn,
        esc(&a.describe),
        a.is_flag,
        if nots.is_empty() { "[]".to_string() } else { format!("[\n        {}\n      ]", nots.join(",\n        ")) },
        a.required,
        a.multiple_values,
        a.multiple_occurs,
        a.num_args.0,
        a.num_args.1,
        match a.delimiter {
            Some(c) => esc(&c.to_string()),
            None => "null".to_string(),
        },
        a.terminated,
        a.prefixed,
        a.assigned,
        default_json(&a.default),
        choice_json(&a.choice),
        opt_str(&a.env),
        a.inherited,
    )
}

fn pos_json(p: &Positional) -> String {
    let nots: Vec<String> = vec![];
    let _ = nots;
    format!(
        "    {{\n      \"id\": {},\n      \"describe\": {},\n      \"notation\": {},\n      \"required\": {},\n      \"multiple\": {},\n      \"delimiter\": {},\n      \"terminated\": {},\n      \"default\": {},\n      \"choice\": {},\n      \"env\": {}\n    }}",
        esc(&p.id),
        esc(&p.describe),
        esc(&p.notation),
        p.required,
        p.multiple,
        match p.delimiter {
            Some(c) => esc(&c.to_string()),
            None => "null".to_string(),
        },
        p.terminated,
        default_json(&p.default),
        choice_json(&p.choice),
        opt_str(&p.env),
    )
}

fn env_json(e: &Env) -> String {
    format!(
        "    {{\n      \"id\": {},\n      \"describe\": {},\n      \"required\": {},\n      \"default\": {},\n      \"choice\": {},\n      \"inherited\": {}\n    }}",
        esc(&e.id),
        esc(&e.describe),
        e.required,
        default_json(&e.default),
        choice_json(&e.choice),
        e.inherited,
    )
}

fn metadata_json(m: &Meta) -> String {
    let mut items: Vec<String> = vec![];
    if let Some(v) = &m.require_tools {
        items.push(format!("    \"require-tools\": {}", esc(v)));
    }
    if let Some(d) = &m.dotenv {
        items.push(format!("    \"dotenv\": {}", match d { Some(x) => esc(x), None => "null".to_string() }));
