use crate::model::*;

#[derive(Clone)]
enum J {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

impl J {
    fn s(v: &str) -> J {
        J::Str(v.to_string())
    }
    fn opt(v: &Option<String>) -> J {
        match v {
            Some(s) => J::s(s),
            None => J::Null,
        }
    }
    fn render(&self, ind: usize) -> String {
        let pad = " ".repeat(ind);
        match self {
            J::Null => "null".to_string(),
            J::Bool(b) => b.to_string(),
            J::Num(n) => n.clone(),
            J::Str(s) => esc(s),
            J::Arr(items) => {
                if items.is_empty() {
                    return "[]".to_string();
                }
                let parts: Vec<String> = items.iter().map(|i| format!("{}{}", pad, i.render(ind))).collect();
                format!("[\n{}\n{}]", parts.join(",\n"), " ".repeat(ind - 2))
            }
            J::Obj(items) => {
                if items.is_empty() {
                    return "{}".to_string();
                }
                let parts: Vec<String> = items
                    .iter()
                    .map(|(k, v)| format!("{}{}: {}", pad, esc(k), v.render(ind)))
                    .collect();
                format!("{{\n{}\n{}}}", parts.join(",\n"), " ".repeat(ind - 2))
            }
        }
    }
}

fn esc(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn choice_json(c: &Option<Choice>) -> J {
    match c {
        None => J::Null,
        Some(Choice::Values(v)) => J::Obj(vec![
            ("type".to_string(), J::s("Values")),
            (
                "data".to_string(),
                J::Arr(v.iter().map(|s| J::s(s)).collect()),
            ),
        ]),
        Some(Choice::Fn(f, validate)) => J::Obj(vec![
            ("type".to_string(), J::s("Fn")),
            ("data".to_string(), J::Arr(vec![J::s(f), J::Bool(*validate)])),
        ]),
    }
}

fn default_json(d: &Option<DefaultVal>) -> J {
    match d {
        None => J::Null,
        Some(DefaultVal::Value(v)) => {
            J::Obj(vec![("type".to_string(), J::s("Value")), ("value".to_string(), J::s(v))])
        }
        Some(DefaultVal::Fn(f)) => {
            J::Obj(vec![("type".to_string(), J::s("Fn")), ("value".to_string(), J::s(f))])
        }
    }
}

fn arg_json(a: &Arg) -> J {
    let nots: Vec<J> = a.notations.iter().map(|s| J::s(s)).collect();
    J::Obj(vec![
        ("id".to_string(), J::s(&a.id)),
        ("long_name".to_string(), J::s(&a.long_name)),
        ("short_name".to_string(), J::opt(&a.short_name)),
        ("describe".to_string(), J::s(&a.describe)),
        ("flag".to_string(), J::Bool(a.is_flag)),
        ("notations".to_string(), J::Arr(nots)),
        ("required".to_string(), J::Bool(a.required)),
        ("multiple_values".to_string(), J::Bool(a.multiple_values)),
        ("multiple_occurs".to_string(), J::Bool(a.multiple_occurs)),
        (
            "num_args".to_string(),
            J::Arr(vec![J::Num(a.num_args.0.to_string()), J::Num(a.num_args.1.to_string())]),
        ),
        (
