{"command": "cd /workspace/examples && python3 - <<'PY'
import json,subprocess
for f in ['options.sh','bind-envs.sh','strict.sh']:
    a=json.loads(subprocess.run(['/workspace/executable','--argc-export',f],capture_output=True,text=True).stdout)
    b=json.loads(subprocess.run(['/tmp/myargc','--argc-export',f],capture_output=True,text=True).stdout)
    def walk(x,y,path):
        if isinstance(x,dict):
            for k in x:
                if k in y: walk(x[k],y[k],path+'.'+k)
        elif isinstance(x,list):
            for i,(u,v) in enumerate(zip(x,y)): walk(u,v,path+f'[{i}]')
        else:
            if x!=y: print(f, path, 'ref=',x,'mine=',y)
    walk(a,b,'')
