use crate::model::*;
use crate::parser::*;
use crate::help::*;

pub fn run(args: &[String]) {
    if args.len() < 3 {
        return;
    }
    let shell = args[0].as_str();
    let file = &args[1];
    let words: Vec<String> = args[2..].to_vec();
    if file.is_empty() {
        return;
    }
    let ps = match load_script(file) {
        Ok(p) => p,
        Err(_) => return,
    };
    // strip the first word (program name)
