use crate::model::*;
use crate::runner::load_script;

fn common_prefix(items: &[String]) -> String {
    if items.is_empty() {
        return String::new();
    }
    let mut p = items[0].clone();
    for it in items {
        let a: Vec<char> = p.chars().collect();
        let b: Vec<char> = it.chars().collect();
        let mut i = 0;
        while i < a.len() && i < b.len() && a[i] == b[i] {
            i += 1;
        }
        p = a[..i].iter().collect();
    }
    p
}

fn is_flag(v: &str) -> bool {
    v.starts_with("--") || v.starts_with('-') || v.starts_with('+')
}
fn is_dir(v: &str) -> bool {
    v.ends_with('/')
}
fn is_file(v: &str) -> bool {
    !v.starts_with('-') && !v.starts_with('+') && !v.contains('/')
}
fn is_sub(v: &str) -> bool {
    !v.starts_with('-') && !v.starts_with('+') && !v.contains('/')
}

fn color_zsh(f: bool, s: bool, fi: bool, d: bool) -> String {
    if fi {
        return if d { "1;34".to_string() } else { "39".to_string() };
    }
    if s {
        return "35".to_string();
    }
    if f {
        "36".to_string()
    } else {
        "1;36".to_string()
    }
}

fn color_elv(f: bool, s: bool, fi: bool, d: bool) -> String {
    if fi {
        return if d { "blue bold".to_string() } else { "default".to_string() };
    }
    if s {
        return "magenta".to_string();
    }
    if f {
        "cyan".to_string()
    } else {
        "cyan bold".to_string()
    }
}

pub fn run(args: &[String]) {
    if args.len() < 3 {
        return;
    }
    let shell = args[0].as_str();
    let file = &args[1];
    let words: Vec<String> = args[2..].to_vec();
    if file.is_empty() {
        return;
    }
    let ps = match load_script(file) {
        Ok(p) => p,
        Err(_) => return,
    };
    let rest: Vec<String> = if words.is_empty() { vec![] } else { words[1..].to_vec() };
    let word = rest.last().cloned().unwrap_or_default();
    let prev: Vec<String> = if rest.is_empty() { vec![] } else { rest[..rest.len() - 1].to_vec() };
    let mut cmd = ps.root.clone();
    for w in &prev {
        if let Some(si) = cmd
            .subcommands
            .iter()
            .position(|s| s.name == *w || s.aliases.iter().any(|a| a == w))
        {
            cmd = cmd.subcommands[si].clone();
        } else if w == "--" {
            break;
        }
    }
    let mut cands: Vec<(String, bool, String)> = vec![];
    if word.starts_with('-') || word.starts_with('+') {
        if let Some(eq) = word.find('=') {
            let name = word[..eq].to_string();
            let pref = word[eq + 1..].to_string();
            if let Some(a) = cmd
                .args
                .iter()
                .find(|a| &a.long_name == &name || a.short_name.as_deref() == Some(&name))
            {
                if let Some(Choice::Values(vs)) = &a.choice {
                    for v in vs {
                        if v.starts_with(&pref) {
                            cands.push((v.clone(), true, String::new()));
                        }
                    }
                }
            }
        } else if word == "--" || word == "+" {
            let sym = if word == "--" { "--" } else { "+" };
            let longs: Vec<String> = cmd
                .args
                .iter()
                .filter(|a| a.long_name.starts_with(sym))
                .map(|a| a.long_name.clone())
                .collect();
            let prefix = common_prefix(&longs);
            if !prefix.is_empty() && prefix.chars().count() > word.chars().count() && shell == "bash"
            {
                cands.push((prefix, false, String::new()));
            } else {
                for a in cmd.args.iter() {
                    if a.long_name.starts_with(sym) {
                        cands.push((a.long_name.clone(), true, a.describe.clone()));
                    }
                }
            }
        } else {
            for a in cmd.args.iter() {
                if a.long_name.starts_with(&word) {
                    cands.push((a.long_name.clone(), true, a.describe.clone()));
                }
                if let Some(s) = &a.short_name {
                    if s.starts_with(&word) {
                        cands.push((s.clone(), true, a.describe.clone()));
                    }
                }
            }
        }
    } else if !cmd.subcommands.is_empty() {
        let show_desc = word.is_empty() || !(shell == "bash" || shell == "tcsh");
        for s in cmd.subcommands.iter() {
            if s.name.starts_with(&word)
                || s.aliases.iter().any(|a| a.starts_with(&word))
            {
                let d = if show_desc { s.describe.clone() } else { String::new() };
                cands.push((s.name.clone(), true, d));
            }
