{"command": "cat > /tmp/dev/argc/src/mangen.rs <<'RSEOF'
use crate::model::*;
use crate::help::*;
use std::path::Path;

fn roff(s: &str) -> String {
    s.replace('-', "\\-")
}

fn man_notations(a: &Arg) -> String {
    let ns = &a.notations;
    if ns.is_empty() {
        return String::new();
    }
    if ns.len() == 1 {
        let n = &ns[0];
        if a.assigned {
            return format!("=\\fI{}\\fR", n);
        }
        if a.multiple_occurs {
            return if a.required {
                format!("=<\\fI{}\\fR>...", n)
            } else {
                format!("=[\\fI{}\\fR]...", n)
            };
        }
        if a.required {
            return format!("=<\\fI{}\\fR>", n);
        }
        return format!("=\\fI{}\\fR", n);
    }
    let parts: Vec<String> = ns.iter().map(|n| format!("\\fI{}\\fR", n)).collect();
    format!(" {}", parts.join(" "))
}

fn man_arg_line(a: &Arg) -> String {
    let mut s = String::new();
    match &a.short_name {
        Some(sh) => {
            s.push_str(&format!("\\fB{}\\fR, ", roff(sh)));
            s.push_str(&format!("\\fB{}\\fR", roff(&a.long_name)));
        }
        None => {
            s.push_str(&format!("\\fB{}\\fR", roff(&a.long_name)));
        }
    }
    s.push_str(&man_notations(a));
    if let Some(DefaultVal::Value(v)) = &a.default {
        s.push_str(&format!(" [default: {}]", roff(v)));
    }
    s
}

fn man_pos_line(p: &Positional) -> String {
    if p.multiple {
        if p.required {
            format!("<\\fI{}\\fR>...", p.notation)
        } else {
            format!("[\\fI{}\\fR]...", p.notation)
        }
    } else if p.required {
        format!("<\\fI{}\\fR>", p.notation)
    } else {
        format!("[\\fI{}\\fR]", p.notation)
    }
}

fn gen_one(cmd: &Cmd, path: &str, out: &mut Vec<String>) {
    let name = path.replace(' ', "-");
    let upper = name.replace('-', "-").to_uppercase();
    let version = cmd.version.clone().unwrap_or_else(|| "0.0.0".to_string());
    out.push(format!(".TH {} 1  \"{} {}\" ", upper, name, version));
    out.push(".SH NAME".to_string());
    if cmd.describe.is_empty() {
        out.push(roff(&name));
    } else {
        out.push(format!("{} \\- {}", roff(&name), roff(&cmd.describe)));
    }
    out.push(".SH SYNOPSIS".to_string());
    let syn = usage_line(cmd, path);
    out.push(format!("\\fB{}\\fR {}", roff(path), roff(&syn[format!("USAGE: {}", path).len()..].trim_start())));
    let mut has_opts = false;
    if !cmd.args.is_empty() || !cmd.positionals.is_empty() {
        has_opts = true;
    }
    if has_opts {
        out.push(".SH OPTIONS".to_string());
        for a in cmd.args.iter() {
            out.push(".TP".to_string());
            out.push(man_arg_line(a));
            if !a.describe.is_empty() {
                out.push(".br".to_string());
                out.push(roff(&a.describe));
            }
            if let Some(Choice::Values(vs)) = &a.choice {
                if !vs.is_empty() {
                    out.push(".br".to_string());
                    out.push(String::new());
                    out.push(".br".to_string());
                    out.push(format!("[\\fIpossible values: \\fR{}]", roff(&vs.join(", "))));
                }
            }
        }
        for p in cmd.positionals.iter() {
            out.push(".TP".to_string());
            out.push(man_pos_line(p));
            if !p.describe.is_empty() {
                out.push(".br".to_string());
                out.push(roff(&p.describe));
            }
        }
    }
    if !cmd.subcommands.is_empty() {
        out.push(".SH SUBCOMMANDS".to_string());
        for s in cmd.subcommands.iter() {
            out.push(".TP".to_string());
            out.push(format!("{}(1)", roff(&format!("{}-{}", name, s.name))));
            if !s.describe.is_empty() {
                out.push(roff(s.describe.split('\n').next().unwrap_or("")));
            }
        }
    }
}

fn walk(cmd: &Cmd, path: &str, dir: &Path, out: &mut Vec<String>) {
    gen_one(cmd, path, out);
    let fname = format!("{}.1", path.replace(' ', "-"));
    let p = dir.join(&fname);
    std::fs::write(&p, out.join("\n") + "\n").unwrap();
    println!("saved {}", p.to_string_lossy());
    out.clear();
    for s in cmd.subcommands.iter() {
        let sp = format!("{} {}", path, s.name);
        walk(s, &sp, dir, out);
    }
}

pub fn generate(ps: &crate::parser::ParsedScript, dirpath: &str) {
    let dir = Path::new(dirpath);
