{"command": "cat > /tmp/dev/argc/src/mangen.rs <<'RSEOF'
use crate::model::*;
use crate::help::*;
use std::path::Path;

fn roff(s: &str) -> String {
    s.replace('-', "\\-")
}

fn man_notations(a: &Arg) -> String {
    let ns = &a.notations;
    if ns.is_empty() {
        return String::new();
    }
    if ns.len() == 1 {
        let n = &ns[0];
        if a.assigned {
            return format!("=\\fI{}\\fR", n);
        }
        if a.multiple_occurs {
            return if a.required {
                format!("=<\\fI{}\\fR>...", n)
            } else {
                format!("=[\\fI{}\\fR]...", n)
            };
        }
        if a.required {
            return format!("=<\\fI{}\\fR>", n);
        }
        return format!("=\\fI{}\\fR", n);
    }
    let parts: Vec<String> = ns.iter().map(|n| format!("\\fI{}\\fR", n)).collect();
    format!(" {}", parts.join(" "))
}

fn man_arg_line(a: &Arg) -> String {
    let mut s = String::new();
    match &a.short_name {
        Some(sh) => {
            s.push_str(&format!("\\fB{}\\fR, ", roff(sh)));
            s.push_str(&format!("\\fB{}\\fR", roff(&a.long_name)));
        }
        None => {
            s.push_str(&format!("\\fB{}\\fR", roff(&a.long_name)));
        }
    }
    s.push_str(&man_notations(a));
    if let Some(DefaultVal::Value(v)) = &a.default {
        s.push_str(&format!(" [default: {}]", roff(v)));
    }
    s
}

fn man_pos_line(p: &Positional) -> String {
    let base = if p.multiple {
        if p.required {
            format!("<\\fI{}\\fR>...", p.notation)
        } else {
            format!("[\\fI{}\\fR]...", p.notation)
        }
    } else if p.required {
        format!("<\\fI{}\\fR>", p.notation)
    } else {
        format!("[\\fI{}\\fR]", p.notation)
    };
    if let Some(DefaultVal::Value(v)) = &p.default {
        return format!("{} [default: {}]", base, roff(v));
    }
    base
}

fn gen_one(cmd: &Cmd, path: &str, out: &mut Vec<String>) {
    let name = path.replace(' ', "-");
    let upper = name.to_uppercase();
    let version = cmd.version.clone().unwrap_or_else(|| "0.0.0".to_string());
    out.push(format!(".TH {} 1  \"{} {}\" ", upper, name, version));
    out.push(".SH NAME".to_string());
    if cmd.describe.is_empty() {
        out.push(roff(&name));
    } else {
        out.push(format!("{} \\- {}", roff(&name), roff(cmd.describe.split('\n').next().unwrap_or(""))));
    }
    out.push(".SH SYNOPSIS".to_string());
    let syn = usage_line(cmd, path);
    let rest = syn.strip_prefix(path).unwrap_or("").to_string();
    out.push(format!("\\fB{}\\fR{}", roff(path), roff(&rest)));
    if cmd.describe.split('\n').count() > 1 {
        out.push(".SH DESCRIPTION".to_string());
        for l in cmd.describe.split('\n') {
            out.push(".br".to_string());
            out.push(roff(l));
        }
    }
    if !cmd.user_args().is_empty() || !cmd.positionals.is_empty() {
        out.push(".SH OPTIONS".to_string());
        for a in cmd.args.iter() {
            out.push(".TP".to_string());
            out.push(man_arg_line(a));
            if a.describe.is_empty() {
                out.push(String::new());
            } else {
                out.push(".br".to_string());
                out.push(roff(&a.describe));
            }
            if let Some(Choice::Values(vs)) = &a.choice {
                if !vs.is_empty() {
                    out.push(".br".to_string());
