{"command": "cat > /tmp/dev/argc/src/build.rs <<'RSEOF'
use crate::model::*;
use crate::help::*;
use crate::parser::*;
use std::path::Path;

fn die(s: &str) -> String {
    format!("_argc_die {}", shell_quote(s))
}

fn cat_block(body: &str) -> String {
    format!("cat <<-'EOF'\n{}\nEOF\n    exit", body)
}

fn gen_usage(cmd: &Cmd, path: &str) -> String {
    let body = build_help_body(cmd, path, None);
    cat_block(&body)
}

fn gen_parse(cmd: &Cmd, path: &str, is_root: bool) -> String {
    let mut out = String::new();
    let subcmds = cmd
        .subcommands
        .iter()
        .flat_map(|s| {
            let mut v = vec![s.name.clone()];
            v.extend(s.aliases.clone());
            v
        })
        .collect::<Vec<_>>()
        .join(", ");
    out.push_str(&format!(
        "_argc_parse{}() {{\n    local _argc_key _argc_action\n    local _argc_subcmds=\"{}\"\n    while [[ $_argc_index -lt $_argc_len ]]; do\n        _argc_item=\"${{argc__args[_argc_index]}}\"\n        _argc_key=\"${{_argc_item%%=*}}\"\n        case \"$_argc_key\" in\n        --help | -help | -h)\n            _argc_usage{}\n            ;;\n",
        if is_root { "" } else { "_" + "" },
        subcmds,
        if is_root { "" } else { "_" }
    ));
    out
}

pub fn generate(args: &[String]) {
    if args.is_empty() {
        eprintln!("No script file provided");
        std::process::exit(1);
    }
    let path = &args[0];
    let ps = match load_script(path) {
        Ok(p) => p,
        Err(e) => {
            crate::runner::report_load(&e);
            std::process::exit(1);
        }
    };
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return,
    };
    let outpath = if args.len() > 1 { args[1].clone() } else { String::new() };
    // strip the eval line
    let mut lines: Vec<&str> = content.split('\n').collect();
    let mut kept: Vec<String> = vec![];
    for l in lines {
        if l.contains("argc --argc-eval") {
            continue;
        }
        kept.push(l.to_string());
    }
    let mut body: Vec<String> = kept;
    while body.last().map_or(false, |l| l.trim().is_empty()) {
        body.pop();
    }
    let mut text = body.join("\n");
    text.push_str("\n\n# ARGC-BUILD {\n# This block was generated by argc (https://github.com/sigoden/argc).\n# Modifying it manually is not recommended\n\n");
    text.push_str(&generate_block(&ps));
    text.push_str("\n# ARGC-BUILD }\n");
    if outpath.is_empty() {
        print!("{}", text);
    } else {
        let p = Path::new(&outpath).to_path_buf();
        let dest = if p.is_dir() {
            p.join(Path::new(path).file_name().unwrap())
        } else {
            p
        };
        std::fs::write(&dest, text).unwrap();
    }
}

fn generate_block(ps: &ParsedScript) -> String {
    let mut s = String::new();
    s.push_str("_argc_run() {\n    if [[ \"${1:-}\" == \"___internal___\" ]]; then\n        _argc_die \"error: unsupported ___internal___ command\"\n    fi\n    if [[ \"${OS:-}\" == \"Windows_NT\" ]] && [[ -n \"${MSYSTEM:-}\" ]]; then\n        set -o igncr\n    fi\n    argc__args=(\"$(basename \"$0\" .sh)\" \"$@\")\n    argc__positionals=()\n    _argc_index=1\n    _argc_len=\"${#argc__args[@]}\"\n    _argc_required_flag_options=()\n    _argc_required_envs=()\n    _argc_tools=()\n    _argc_parse\n    if [ -n \"${argc__fn:-}\" ]; then\n        $argc__fn \"${argc__positionals[@]}\"\n    fi\n}\n\n");
    s.push_str(&format!("_argc_usage() {{\n    {}\n}}\n\n", gen_usage(&ps.root, &ps.root.name)));
    s.push_str(&format!("_argc_version() {{\n    echo {}\n    exit\n}}\n\n", crate::eval::version_text(&ps.root, &ps.root.name)));
    s.push_str(&helpers());
    s.push_str("\n_argc_run \"$@\"\n");
    s
}

fn helpers() -> String {
    r#"_argc_parse() {
    :
}

_argc_take_args() {
    _argc_take_args_values=()
    _argc_take_args_len=0
    local param="$1" min="$2" max="$3" signs="$4" delimiter="$5"
    if [[ "$min" -eq 0 ]] && [[ "$max" -eq 0 ]]; then
        return
    fi
    local _argc_take_index=$((_argc_index + 1)) _argc_take_value
    if [[ "$_argc_item" == *=* ]]; then
        _argc_take_args_values=("${_argc_item##*=}")
    else
        while [[ $_argc_take_index -lt $_argc_len ]]; do
            _argc_take_value="${argc__args[_argc_take_index]}"
            if _argc_maybe_flag_option "$signs" "$_argc_take_value"; then
                if [[ "${#_argc_take_value}" -gt 1 ]]; then
                    break
                fi
            fi
            _argc_take_args_values+=("$_argc_take_value")
            _argc_take_args_len=$((_argc_take_args_len + 1))
            if [[ "$_argc_take_args_len" -ge "$max" ]]; then
                break
            fi
            _argc_take_index=$((_argc_take_index + 1))
        done
    fi
    if [[ "${#_argc_take_args_values[@]}" -lt "$min" ]]; then
        _argc_die "error: incorrect number of values for \`$param\`"
    fi
