fn gen_usage_fns(cmd: &Cmd, path: &str, out: &mut Vec<String>) {
    let uname = if path.is_empty() {
        "_argc_usage".to_string()
    } else {
        format!("_argc_usage_{}", path.replace(' ', "_"))
    };
    out.push(format!("{}() {{\n    {}\n}}\n\n", uname, gen_usage(cmd, path)));
    for s in cmd.subcommands.iter() {
        let sp = if path.is_empty() { s.name.clone() } else { format!("{} {}", path, s.name) };
        gen_usage_fns(s, &sp, out);
    }
}

fn walk_parse(cmd: &Cmd, path: &str, uname: &str, out: &mut Vec<String>) {
    if cmd.subcommands.is_empty() {
        gen_leaf_parse(cmd, path, uname, out);
    } else {
        gen_parent_parse(cmd, path, uname, out);
        for s in cmd.subcommands.iter() {
            let sp = if path.is_empty() { s.name.clone() } else { format!("{} {}", path, s.name) };
            let su = format!("_argc_usage_{}", sp.replace(' ', "_"));
            walk_parse(s, &sp, &su, out);
        }
    }
}

pub fn generate(args: &[String]) {
    if args.is_empty() {
        eprintln!("No script file provided");
        std::process::exit(1);
    }
    let path = &args[0];
    let ps = match load_script(path) {
        Ok(p) => p,
        Err(e) => {
            crate::runner::report_load(&e);
            std::process::exit(1);
        }
    };
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return,
    };
    let outpath = if args.len() > 1 { args[1].clone() } else { String::new() };
    let mut body: Vec<String> = vec![];
    for l in content.split('\n') {
        if l.contains("argc --argc-eval") {
            continue;
        }
        body.push(l.to_string());
    }
    while body.last().map_or(false, |l| l.trim().is_empty()) {
        body.pop();
    }
    let mut text = body.join("\n");
    text.push_str("\n\n# ARGC-BUILD {\n# This block was generated by argc (https://github.com/sigoden/argc).\n# Modifying it manually is not recommended\n\n");
    let mut fns: Vec<String> = vec![];
    gen_usage_fns(&ps.root, "", &mut fns);
    fns.push(format!("_argc_version() {{\n    echo {}\n    exit\n}}\n", crate::eval::version_text(&ps.root, &ps.root.name)));
    let mut parses: Vec<String> = vec![];
    walk_parse(&ps.root, "", "_argc_usage", &mut parses);
    fns.push("_argc_run() {\n    if [[ \"${1:-}\" == \"___internal___\" ]]; then\n        _argc_die \"error: unsupported ___internal___ command\"\n    fi\n    if [[ \"${OS:-}\" == \"Windows_NT\" ]] && [[ -n \"${MSYSTEM:-}\" ]]; then\n        set -o igncr\n    fi\n    argc__args=(\"$(basename \"$0\" .sh)\" \"$@\")\n    argc__positionals=()\n    _argc_index=1\n    _argc_len=\"${#argc__args[@]}\"\n    _argc_required_flag_options=()\n    _argc_required_envs=()\n    _argc_tools=()\n    _argc_parse\n    if [ -n \"${argc__fn:-}\" ]; then\n        $argc__fn \"${argc__positionals[@]}\"\n    fi\n}\n\n".to_string());
    for f in fns {
        text.push_str(&f);
        text.push_str("\n");
    }
    for p in parses {
        text.push_str(&p);
    }
    text.push_str(&helpers());
    text.push_str("\n_argc_run \"$@\"\n\n");
    if outpath.is_empty() {
        print!("{}", text);
    } else {
        let p = Path::new(&outpath).to_path_buf();
        let dest = if p.is_dir() {
            p.join(Path::new(path).file_name().unwrap())
        } else {
            p
        };
        std::fs::write(&dest, text).unwrap();
    }
}

fn helpers() -> &'static str {
    r#"_argc_take_args() {
    _argc_take_args_values=()
    _argc_take_args_len=0
    local param="$1" min="$2" max="$3" signs="$4" delimiter="$5"
    if [[ "$min" -eq 0 ]] && [[ "$max" -eq 0 ]]; then
        return
    fi
    local _argc_take_index=$((_argc_index + 1)) _argc_take_value
    if [[ "$_argc_item" == *=* ]]; then
        _argc_take_args_values=("${_argc_item##*=}")
    else
        while [[ $_argc_take_index -lt $_argc_len ]]; do
            _argc_take_value="${argc__args[_argc_take_index]}"
            if _argc_maybe_flag_option "$signs" "$_argc_take_value"; then
                if [[ "${#_argc_take_value}" -gt 1 ]]; then
                    break
                fi
            fi
            _argc_take_args_values+=("$_argc_take_value")
            _argc_take_args_len=$((_argc_take_args_len + 1))
            if [[ "$_argc_take_args_len" -ge "$max" ]]; then
                break
            fi
            _argc_take_index=$((_argc_take_index + 1))
        done
    fi
    if [[ "${#_argc_take_args_values[@]}" -lt "$min" ]]; then
        _argc_die "error: incorrect number of values for \`$param\`"
    fi
    if [[ -n "$delimiter" ]] && [[ "${#_argc_take_args_values[@]}" -gt 0 ]]; then
        local item values arr=()
        for item in "${_argc_take_args_values[@]}"; do
            IFS="$delimiter" read -r -a values <<<"$item"
            arr+=("${values[@]}")
        done
        _argc_take_args_values=("${arr[@]}")
    fi
}

_argc_match_positionals() {
    _argc_match_positionals_values=()
    _argc_match_positionals_len=0
    local params=("$@")
    local args_len="${#argc__positionals[@]}"
    if [[ $args_len -eq 0 ]]; then
        return
    fi
    local params_len=$# arg_index=0 param_index=0
    while [[ $param_index -lt $params_len && $arg_index -lt $args_len ]]; do
        local takes=0
        if [[ "${params[param_index]}" -eq 1 ]]; then
            if [[ $param_index -eq 0 ]] &&
                [[ ${_argc_dash:-} -gt 0 ]] &&
                [[ $params_len -eq 2 ]] &&
                [[ "${params[$((param_index + 1))]}" -eq 1 ]] \
                ; then
                takes=${_argc_dash:-}
            else
                local arg_diff=$((args_len - arg_index)) param_diff=$((params_len - param_index))
                if [[ $arg_diff -gt $param_diff ]]; then
                    takes=$((arg_diff - param_diff + 1))
                else
                    takes=1
                fi
            fi
        else
            takes=1
        fi
        _argc_match_positionals_values+=("$arg_index:$takes")
        arg_index=$((arg_index + takes))
        param_index=$((param_index + 1))
    done
    if [[ $arg_index -lt $args_len ]]; then
        _argc_match_positionals_values+=("$arg_index:$((args_len - arg_index))")
    fi
    _argc_match_positionals_len=${#_argc_match_positionals_values[@]}
    if [[ $params_len -gt 0 ]] && [[ $_argc_match_positionals_len -gt $params_len ]]; then
        local index="${_argc_match_positionals_values[params_len]%%:*}"
        _argc_die "error: unexpected argument \`${argc__positionals[index]}\` found"
    fi
}

_argc_maybe_flag_option() {
    local signs="$1" arg="$2"
    if [[ -z "$signs" ]]; then
        return 1
    fi
    local cond=false
    if [[ "$signs" == *"+"* ]]; then
        if [[ "$arg" =~ ^\+[^+].* ]]; then
            cond=true
        fi
    elif [[ "$arg" == -* ]]; then
        if (( ${#arg} < 3 )) || [[ ! "$arg" =~ ^---.* ]]; then
            cond=true
        fi
    fi
    if [[ "$cond" == "false" ]]; then
        return 1
    fi
    local value="${arg%%=*}"
    if [[ "$value" =~ [[:space:]] ]]; then
        return 1
    fi
    return 0
}

_argc_die() {
    if [[ $# -eq 0 ]]; then
        cat
    else
        echo "$*" >&2
    fi
    exit 1
}

_argc_require_tools() {
    local tool missing_tools=()
    for tool in "$@"; do
        if ! command -v "$tool" >/dev/null 2>&1; then
            missing_tools+=("$tool")
        fi
    done
    if [[ "${#missing_tools[@]}" -gt 0 ]]; then
        echo "error: missing tools: ${missing_tools[*]}" >&2
        exit 1
    fi
}

_argc_load_dotenv() {
    local env_file="$1" env_vars=""
    if [[ -f "$env_file" ]]; then
        while IFS='=' read -r key value; do
            if [[ "$key" == $'#'* ]] || [[ -z "$key" ]]; then
                continue
            fi
            if [[ -z "${!key+x}" ]]; then
                env_vars="$env_vars $key=$value"
            fi
        done < <(cat "$env_file"; echo "")
        if [[ -n "$env_vars" ]]; then
            eval "export $env_vars"
        fi
    fi
}
